import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum UserRole {
  ADMIN = 'ADMIN',
  MANAGER = 'MANAGER',
  OPERATOR = 'OPERATOR'
}

export enum Sector {
  OPERATIONS = 'Operacional',
  FINANCE = 'Financeiro',
  HR = 'RH',
  MARKETING = 'Marketing'
}

export interface Task {
  id: string;
  title: string;
  description: string;
  status: 'PENDING' | 'IN_PROGRESS' | 'COMPLETED';
  priority: 'LOW' | 'MEDIUM' | 'HIGH';
  sector: Sector;
  frequency: 'DAILY' | 'WEEKLY' | 'ONCE';
  dueDate?: string;
}

export interface User {
  id: string;
  name: string;
  role: UserRole;
  sector?: Sector;
}

export interface AppState {
  currentUser: User;
  tasks: Task[];
}

import { GoogleGenAI, Type } from "@google/genai";

const getAIClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
};

export const generateTaskSummary = async (tasks: any[]) => {
  const ai = getAIClient();
  const prompt = `Analyze these workspace tasks and provide a 3-sentence executive summary on productivity and urgent priorities: ${JSON.stringify(tasks)}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Não foi possível carregar o resumo da IA no momento.";
  }
};

export const suggestOptimizedWorkflow = async (tasks: any[]) => {
  const ai = getAIClient();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Com base nessas tarefas: ${JSON.stringify(tasks)}. Sugira uma ordem de execução otimizada focando em eficiência máxima para uma equipe de alta performance. Retorne apenas o JSON com { "suggestions": string[] }.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          suggestions: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["suggestions"]
      }
    }
  });

  return JSON.parse(response.text);
};

