import { GoogleGenAI, Type } from "@google/genai";

// Always use named parameter with direct process.env.API_KEY reference
const getAIClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const generateTaskSummary = async (tasks: any[]) => {
  const ai = getAIClient();
  const prompt = `Analyze these workspace tasks and provide a 3-sentence executive summary on productivity and urgent priorities: ${JSON.stringify(tasks)}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    // Use the .text property directly, not a method call
    return response.text;
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Não foi possível carregar o resumo da IA no momento.";
  }
};

export const suggestOptimizedWorkflow = async (tasks: any[]) => {
  const ai = getAIClient();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Com base nessas tarefas: ${JSON.stringify(tasks)}. Sugira uma ordem de execução otimizada focando em eficiência máxima para uma equipe de alta performance. Retorne apenas o JSON com { "suggestions": string[] }.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          suggestions: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["suggestions"]
      }
    }
  });

  // Access the .text property directly and parse the returned JSON string
  const text = response.text || '{"suggestions": []}';
  return JSON.parse(text);
};

