  }
};

export const suggestOptimizedWorkflow = async (tasks: any[]) => {
  const ai = getAIClient();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Com base nessas tarefas: ${JSON.stringify(tasks)}. Sugira uma ordem de execução otimizada focando em eficiência máxima para uma equipe de alta performance. Retorne apenas o JSON com { "suggestions": string[] }.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            suggestions: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["suggestions"]
        }
      }
    });
    const text = response.text || '{"suggestions": []}';
    return JSON.parse(text);
  } catch (error) {
    console.error("Error optimizing workflow:", error);
    return { suggestions: ["Focar nas tarefas de alta prioridade primeiro", "Agrupar tarefas por setor para reduzir perda de contexto"] };
  }
};

export const chatWithOmega = async (message: string, context: any[]) => {
  const ai = getAIClient();
  const prompt = `Você é a IA Omega, o assistente central de um sistema de gestão de alta performance. 
  Contexto atual do workspace (tarefas): ${JSON.stringify(context)}.
  Usuário pergunta: ${message}`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
  });
  return response.text;
};

