import React, { useState } from 'react';
import { UserRole, Task, Sector } from './types';
import { INITIAL_TASKS } from './constants';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import ChecklistView from './components/ChecklistView';
import TeamView from './components/TeamView';
import { suggestOptimizedWorkflow, chatWithOmega } from './services/geminiService';
import { Bell, Search, Sparkles, Send, Loader2, Info } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [userRole, setUserRole] = useState<UserRole>(UserRole.ADMIN);
  const [tasks, setTasks] = useState<Task[]>([...INITIAL_TASKS]);

  // State for AI Assistant
  const [chatMessage, setChatMessage] = useState('');
  const [chatHistory, setChatHistory] = useState<{role: 'user' | 'ai', text: string}[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [aiSuggestions, setAiSuggestions] = useState<string[]>([]);

  const toggleTask = (id: string) => {
    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: t.status === 'COMPLETED' ? 'PENDING' : 'COMPLETED' } : t));
  };

  const handleSendToAi = async () => {
    if (!chatMessage.trim()) return;
    const msg = chatMessage;
    setChatMessage('');
    setChatHistory(prev => [...prev, { role: 'user', text: msg }]);
    setIsAiLoading(true);

    const response = await chatWithOmega(msg, tasks);
    setChatHistory(prev => [...prev, { role: 'ai', text: response || 'Sem resposta.' }]);
    setIsAiLoading(false);
  };

  const handleOptimize = async () => {
    setIsAiLoading(true);
    const result = await suggestOptimizedWorkflow(tasks);
    setAiSuggestions(result.suggestions);
    setIsAiLoading(false);
    setActiveTab('ai-assistant');
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard tasks={tasks} role={userRole} />;
      case 'checklists':
        return <ChecklistView tasks={tasks} toggleTask={toggleTask} />;
      case 'team':
        return <TeamView />;
      case 'ai-assistant':
        return (
          <div className="max-w-4xl mx-auto space-y-6 animate-in zoom-in-95 duration-500">
            <div className="flex items-center justify-between">
              <h2 className="text-3xl font-black text-white tracking-tighter uppercase italic">IA Omega</h2>
              <div className="flex gap-2">
                 <button 
                  onClick={handleOptimize}
                  className="px-4 py-2 bg-teal-500 text-black font-black text-xs rounded-lg hover:scale-105 transition-transform flex items-center gap-2"
                >
                  <Sparkles className="w-4 h-4" /> OTIMIZAR AGORA
                </button>
              </div>
            </div>

            <div className="bg-[#111111] border border-white/5 rounded-2xl flex flex-col h-[600px] overflow-hidden">
              <div className="flex-1 overflow-y-auto p-6 space-y-4">
                {chatHistory.length === 0 && (
                  <div className="flex flex-col items-center justify-center h-full text-center space-y-4 opacity-50">
                    <div className="w-16 h-16 bg-white/5 rounded-full flex items-center justify-center">
                      <Sparkles className="w-8 h-8 text-teal-400" />
                    </div>
                    <div>
                      <p className="text-white font-bold text-lg">Assistente Executivo</p>
                      <p className="text-sm">Peça um resumo, otimize o cronograma ou gerencie sua equipe.</p>
                    </div>
                  </div>
                )}

                {chatHistory.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                    <div className={`max-w-[80%] p-4 rounded-2xl text-sm leading-relaxed ${
                      msg.role === 'user' ? 'bg-teal-500 text-black font-medium' : 'bg-white/5 text-gray-300 border border-white/10'
                    }`}>
                      {msg.text}
                    </div>
                  </div>
                ))}

                {aiSuggestions.length > 0 && (
                  <div className="bg-blue-500/10 border border-blue-500/20 p-6 rounded-2xl space-y-3">
                    <div className="flex items-center gap-2 text-blue-400 font-bold text-sm">
                      <Info className="w-4 h-4" /> Sugestões de Fluxo Otimizado
                    </div>
                    <ul className="space-y-2">
                      {aiSuggestions.map((s, i) => (
                        <li key={i} className="text-sm text-blue-200/80 flex items-start gap-2">
                          <span className="mt-1.5 w-1.5 h-1.5 rounded-full bg-blue-400 shrink-0" />
                          {s}
                        </li>
                      ))}
                    </ul>
                  </div>
                )}

                {isAiLoading && (
                  <div className="flex justify-start">
                    <div className="bg-white/5 border border-white/10 p-4 rounded-2xl flex items-center gap-2 text-sm text-gray-500 italic">
                      <Loader2 className="w-4 h-4 animate-spin" /> Omega está processando dados...
                    </div>
                  </div>
                )}
              </div>

              <div className="p-4 bg-[#1a1a1a] border-t border-white/5">
                <form 
                  onSubmit={(e) => { e.preventDefault(); handleSendToAi(); }}
                  className="flex gap-2"
                >
                  <input 
                    value={chatMessage}
                    onChange={(e) => setChatMessage(e.target.value)}
                    placeholder="Digite sua dúvida estratégica..."
                    className="flex-1 bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-teal-500 transition-colors text-white"
                  />
                  <button 
                    disabled={isAiLoading}
                    className="p-3 bg-teal-500 rounded-xl text-black hover:bg-teal-400 transition-colors disabled:opacity-50"
                  >
                    <Send className="w-5 h-5" />
                  </button>
                </form>
              </div>
            </div>
          </div>
        );
      default:
        return (
          <div className="flex flex-col items-center justify-center h-full opacity-50">
            <h3 className="text-xl font-black text-white italic uppercase">{activeTab}</h3>
            <p className="text-sm">Funcionalidade em fase de homologação.</p>
          </div>
        );
    }
  };

  return (
    <div className="flex h-screen bg-[#0a0a0a] text-gray-300 overflow-hidden">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} role={userRole} />

      <main className="flex-1 flex flex-col h-full overflow-hidden relative">
        <header className="h-16 border-b border-white/5 bg-[#0a0a0a]/50 backdrop-blur-md flex items-center justify-between px-8 z-10">
          <div className="relative w-96 max-w-full">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
            <input 
              type="text" 
              placeholder="Pesquisar operações..." 
              className="w-full bg-white/5 border border-white/10 rounded-full py-2 pl-10 pr-4 text-sm focus:outline-none focus:border-teal-500/50 transition-colors"
            />
          </div>

          <div className="flex items-center gap-6">
            <div className="hidden sm:flex items-center gap-2">
              <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Acesso:</span>
              <select 
                value={userRole} 
                onChange={(e) => setUserRole(e.target.value as UserRole)}
                className="bg-white/5 border border-white/10 rounded px-2 py-1 text-xs font-bold text-teal-400 outline-none hover:border-white/20 transition-colors cursor-pointer"
              >
                <option value={UserRole.ADMIN}>ADMIN</option>
                <option value={UserRole.MANAGER}>MANAGER</option>
                <option value={UserRole.OPERATOR}>OPERATOR</option>
              </select>
            </div>

            <button className="relative p-2 text-gray-400 hover:text-white transition-colors">
              <Bell className="w-5 h-5" />
              <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full border-2 border-[#0a0a0a]"></span>
            </button>

            <div className="flex items-center gap-3 pl-4 border-l border-white/10">
              <div className="text-right hidden md:block">
                <p className="text-sm font-bold text-white leading-tight">Admin Principal</p>
                <p className="text-[10px] text-gray-500 uppercase font-black">Nível 99</p>
              </div>
              <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-teal-500 to-emerald-400 flex items-center justify-center font-bold text-white border-2 border-white/10">
                A
              </div>
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-8 custom-scrollbar relative z-0">
          {renderContent()}
        </div>

        <div className="fixed bottom-0 right-0 p-4 opacity-10 pointer-events-none z-[-1]">
          <p className="text-[100px] font-black text-white select-none tracking-tighter leading-none italic uppercase">Omega</p>
        </div>
      </main>
    </div>
  );
};

