    setIsAiLoading(false);
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard clients={clients} />;
      case 'clients':
        return <ClientBoard clients={clients} />;
      case 'team':
        return <TeamView />;
      case 'ai-assistant':
