            </div>
          </div>
        );
      default:
        return (
          <div className="flex flex-col items-center justify-center h-full opacity-30 italic">
            <p>Módulo {activeTab} em integração...</p>
          </div>
        );
    }
  };

  return (
    <div className="flex h-screen bg-[#080808] text-gray-300 overflow-hidden font-inter selection:bg-teal-500 selection:text-black">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} role={userRole} />

      <main className="flex-1 flex flex-col h-full overflow-hidden relative">
        <header className="h-16 border-b border-white/5 bg-[#080808]/80 backdrop-blur-xl flex items-center justify-between px-8 z-10">
          <div className="flex items-center gap-4">
             <div className="w-2 h-2 bg-teal-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(20,184,166,0.8)]"></div>
             <p className="text-[10px] font-black uppercase tracking-widest text-gray-500">Central de Inteligência Operacional</p>
          </div>

          <div className="flex items-center gap-6">
            <select 
