export const generateTaskSummary = async (clients: any[]) => {
  const ai = getAIClient();
  const prompt = `Você é um consultor estratégico de Customer Success. Analise esta carteira de clientes: ${JSON.stringify(clients)}. 
  Dê um resumo executivo de 2 linhas focando em qual segmento precisa de atenção imediata e qual o potencial de expansão de receita (upsell).`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    return "Analise suspensa. Verifique os KPIs manualmente.";
  }
};

export const chatWithOmega = async (message: string, context: any[]) => {
  const ai = getAIClient();
  const prompt = `Você é a IA Omega, o cérebro por trás de uma operação de Sucesso do Cliente de elite.
  Contexto da Carteira Atual: ${JSON.stringify(context)}.
  O CEO pergunta: ${message}.
  Seja direto, data-driven e aja como um braço direito estratégico.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    return "Erro na conexão com o Core Inteligente.";
  }
};

