import React, { useState, useEffect } from 'react';
import { UserRole, Client, Task, User } from './types';
import { INITIAL_CLIENTS, NAVIGATION_ITEMS, MANAGERS } from './constants';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import SquadsView from './components/SquadsView';
import ChecklistView from './components/ChecklistView';
import ManagerWorkspace from './components/ManagerWorkspace';
import { Bell, Search, LogOut } from 'lucide-react';

const App: React.FC = () => {
  // Estado Inicial do Usuário (CEO por padrão para visualização)
  const [currentUser, setCurrentUser] = useState<User>({ id: 'ceo', name: 'CEO Omega', role: UserRole.CEO });

  // Persistência com LocalStorage
  const [activeTab, setActiveTab] = useState('dashboard');
  const [clients, setClients] = useState<Client[]>(() => {
    const saved = localStorage.getItem('omega_clients');
    return saved ? JSON.parse(saved) : INITIAL_CLIENTS;
  });
  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('omega_tasks');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('omega_clients', JSON.stringify(clients));
  }, [clients]);

  useEffect(() => {
    localStorage.setItem('omega_tasks', JSON.stringify(tasks));
  }, [tasks]);

  // Handlers
  const handleAssignManager = (clientId: string, managerId: string) => {
    setClients(prev => prev.map(c => c.id === clientId ? { ...c, managerId } : c));
  };

  const handleUpdateNotes = (clientId: string, notes: string) => {
    setClients(prev => prev.map(c => c.id === clientId ? { ...c, notes } : c));
  };

  const handleAddTask = (taskData: Partial<Task>) => {
    const newTask = { ...taskData, id: Math.random().toString(36).substr(2, 9) } as Task;
    setTasks(prev => [newTask, ...prev]);
  };

  const handleRemoveTask = (id: string) => {
    setTasks(prev => prev.filter(t => t.id !== id));
  };

  const handleToggleTask = (id: string) => {
    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: t.status === 'COMPLETED' ? 'PENDING' : 'COMPLETED' } : t));
  };

  const handleSwitchUser = (userId: string) => {
    if (userId === 'ceo') {
      setCurrentUser({ id: 'ceo', name: 'CEO Omega', role: UserRole.CEO });
      setActiveTab('dashboard');
    } else {
      const manager = MANAGERS.find(m => m.id === userId);
      if (manager) {
        setCurrentUser({ id: manager.id, name: manager.name, role: UserRole.MANAGER });
        setActiveTab('my-workspace');
      }
    }
  };

  const renderContent = () => {
    // Bloqueio de tabs por role
    const currentNavItem = NAVIGATION_ITEMS.find(item => item.id === activeTab);
    if (currentNavItem && !currentNavItem.roles.includes(currentUser.role)) {
      return <div className="p-10 text-center text-gray-500 italic">Acesso restrito ao nível operacional {currentUser.role}.</div>;
    }

    switch (activeTab) {
      case 'dashboard':
        return <Dashboard clients={clients} />;
      case 'clients':
        return <SquadsView clients={clients} onAssignManager={handleAssignManager} />;
      case 'checklists':
        return <ChecklistView tasks={tasks} onAddTask={handleAddTask} onRemoveTask={handleRemoveTask} />;
      case 'my-workspace':
        return (
          <ManagerWorkspace 
            managerId={currentUser.id} 
            clients={clients} 
            tasks={tasks} 
            onToggleTask={handleToggleTask}
            onUpdateNotes={handleUpdateNotes}
          />
        );
      default:
        return <div className="p-10 text-center opacity-30">Selecione uma aba no menu lateral.</div>;
    }
  };

  return (
    <div className="flex h-screen bg-[#080808] text-gray-300 overflow-hidden font-inter">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} role={currentUser.role} />

      <main className="flex-1 flex flex-col h-full overflow-hidden relative">
        <header className="h-16 border-b border-white/5 bg-[#080808]/80 backdrop-blur-xl flex items-center justify-between px-8 z-10">
          <div className="flex items-center gap-4">
             <div className="w-2 h-2 bg-teal-500 rounded-full shadow-[0_0_8px_rgba(20,184,166,0.5)]"></div>
             <p className="text-[10px] font-black uppercase tracking-widest text-gray-500 italic">Omega Operational Core</p>
          </div>

          <div className="flex items-center gap-6">
            <div className="flex items-center gap-2">
              <span className="text-[10px] font-black text-gray-500 uppercase tracking-tighter">Logado como:</span>
              <select 
                value={currentUser.id === 'ceo' ? 'ceo' : currentUser.id}
                onChange={(e) => handleSwitchUser(e.target.value)}
                className="bg-white/5 border border-white/10 rounded px-3 py-1 text-[10px] font-black text-teal-400 outline-none hover:border-white/20 transition-colors cursor-pointer uppercase"
              >
                <option value="ceo">CEO Omega</option>
                {MANAGERS.map(m => (
                  <option key={m.id} value={m.id}>{m.name}</option>
                ))}
              </select>
            </div>

            <div className="w-px h-6 bg-white/10"></div>

            <div className="flex items-center gap-3">
              <div className="text-right">
                <p className="text-xs font-black text-white leading-none uppercase tracking-tighter">{currentUser.name}</p>
                <p className="text-[10px] text-gray-500 uppercase font-black">{currentUser.role === 'CEO' ? 'Strategic Admin' : 'Traffic Manager'}</p>
              </div>
              <div className={`w-8 h-8 rounded-lg flex items-center justify-center font-black text-xs ${currentUser.role === 'CEO' ? 'bg-teal-500 text-black' : 'bg-white/10 text-white'}`}>
                {currentUser.name[0]}
              </div>
            </div>
