import React, { useState, useEffect } from 'react';
import { UserRole, Client, Task, User } from './types';
import { INITIAL_CLIENTS, NAVIGATION_ITEMS, MANAGERS } from './constants';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import SquadsView from './components/SquadsView';
import ChecklistView from './components/ChecklistView';
import ManagerWorkspace from './components/ManagerWorkspace';
import ClientBoard from './components/ClientBoard';
import TeamView from './components/TeamView';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User>({ id: 'ceo', name: 'Diretor Omega', role: UserRole.CEO });
  const [activeTab, setActiveTab] = useState('dashboard');

  const [clients, setClients] = useState<Client[]>(() => {
    const saved = localStorage.getItem('omega_clients_pro');
    return saved ? JSON.parse(saved) : INITIAL_CLIENTS;
  });

  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('omega_tasks_pro');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('omega_clients_pro', JSON.stringify(clients));
  }, [clients]);

  useEffect(() => {
    localStorage.setItem('omega_tasks_pro', JSON.stringify(tasks));
  }, [tasks]);

  const handleAssignManager = (clientId: string, managerId: string) => {
    setClients(prev => prev.map(c => c.id === clientId ? { ...c, managerId } : c));
  };

  const handleUpdateNotes = (clientId: string, notes: string) => {
    setClients(prev => prev.map(c => c.id === clientId ? { ...c, notes } : c));
  };

  const handleAddTask = (taskData: Partial<Task>) => {
    const newTask = { 
      ...taskData, 
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString()
    } as Task;
    setTasks(prev => [newTask, ...prev]);
  };

  const handleRemoveTask = (id: string) => {
    setTasks(prev => prev.filter(t => t.id !== id));
  };

  const handleToggleTask = (id: string) => {
    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: t.status === 'COMPLETED' ? 'PENDING' : 'COMPLETED' } : t));
  };

  const handleSwitchUser = (userId: string) => {
    if (userId === 'ceo') {
      setCurrentUser({ id: 'ceo', name: 'Diretor Omega', role: UserRole.CEO });
    } else {
      const manager = MANAGERS.find(m => m.id === userId);
      if (manager) {
        setCurrentUser({ id: manager.id, name: manager.name, role: UserRole.MANAGER });
      }
    }
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard clients={clients} tasks={tasks} />;
      case 'my-workspace':
        return (
          <ManagerWorkspace 
            managerId={currentUser.id} 
            clients={clients} 
            tasks={tasks} 
            onToggleTask={handleToggleTask}
            onUpdateNotes={handleUpdateNotes}
          />
        );
      case 'clients':
        return <SquadsView clients={clients} onAssignManager={handleAssignManager} />;
      case 'checklists':
        return <ChecklistView tasks={tasks} onAddTask={handleAddTask} onRemoveTask={handleRemoveTask} />;
      case 'team':
        return <TeamView />;
      case 'notes':
        return (
           <div className="space-y-6">
             <h2 className="text-2xl font-bold text-white">Wiki & Notas Gerais</h2>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {clients.map(c => (
                  <div key={c.id} className="bg-[#111] border border-white/5 p-6 rounded-2xl space-y-4">
                    <h4 className="font-bold text-white uppercase text-xs tracking-widest">{c.name}</h4>
                    <textarea 
                      value={c.notes || ''}
                      onChange={(e) => handleUpdateNotes(c.id, e.target.value)}
                      placeholder="Anote detalhes técnicos aqui..."
                      className="w-full bg-[#0a0a0a] border border-white/5 rounded-xl p-4 text-xs text-gray-400 min-h-[100px] outline-none focus:border-[#14b8a6]/30 transition-all"
                    />
                  </div>
                ))}
             </div>
           </div>
        );
      default:
        return <div className="p-10 text-center opacity-30">Selecione uma aba no menu lateral.</div>;
    }
  };

  return (
    <div className="flex h-screen bg-[#0a0a0a] text-gray-300 overflow-hidden font-inter selection:bg-[#14b8a6] selection:text-black">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        currentUser={currentUser} 
        onSwitchUser={handleSwitchUser}
      />

      <main className="flex-1 flex flex-col h-full overflow-hidden relative">
        <div className="flex-1 overflow-y-auto p-12 custom-scrollbar z-0">
          {renderContent()}
        </div>

        {/* Glow effect background */}
        <div className="fixed top-[-100px] right-[-100px] w-[600px] h-[600px] bg-[#14b8a6]/5 blur-[150px] rounded-full pointer-events-none -z-10"></div>
      </main>
    </div>
  );
};

