                  {task.status === 'COMPLETED' ? <CheckCircle2 className="w-5 h-5 text-teal-500" /> : <Circle className="w-5 h-5 text-gray-600" />}
                  <div className="flex-1">
                    <p className={`text-sm font-bold ${task.status === 'COMPLETED' ? 'text-gray-600 line-through' : 'text-white'}`}>{task.title}</p>
                    <span className="text-[10px] text-gray-500 uppercase font-black tracking-widest">{task.type}</span>
                  </div>
                </button>
              ))
            )}
          </div>
        </div>

        {/* Meus Clientes e Notas */}
        <div className="lg:col-span-2 space-y-4">
          <h3 className="text-lg font-bold text-white flex items-center gap-2">
