                        <button
                          key={flag}
                          onClick={() => onUpdateStatusFlag(client.id, flag)}
                          className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all ${
                            client.statusFlag === flag 
                              ? (flag === 'GREEN' ? 'bg-green-500 text-black' : flag === 'YELLOW' ? 'bg-yellow-500 text-black' : 'bg-red-500 text-white')
                              : 'bg-white/5 text-gray-600 hover:bg-white/10'
                          }`}
