                    <StickyNote className="w-3 h-3" /> Notas Estratégicas do Cliente
                  </div>
                  <textarea 
                    value={client.notes || ''}
                    onChange={(e) => onUpdateNotes(client.id, e.target.value)}
                    placeholder="Anote aqui informações importantes do cliente, acessos, metas..."
                    className="w-full bg-[#0a0a0a] border border-white/5 rounded-2xl p-6 text-sm text-gray-300 min-h-[150px] focus:border-teal-500/50 outline-none resize-none transition-all"
                  />
                </div>
              </div>
            ))}
            {myClients.length === 0 && (
              <div className="bg-[#111] border border-dashed border-white/10 rounded-[32px] p-20 text-center">
                 <p className="text-gray-600 uppercase font-black text-xs tracking-widest">Nenhum cliente atribuído a você.</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

