import React, { useState, useEffect } from 'react';
import { UserRole, Client, Task, User, MonthlyData, ClientStatus } from './types';
import { INITIAL_CLIENTS, NAVIGATION_ITEMS, MANAGERS, MONTHS } from './constants';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import SquadsView from './components/SquadsView';
import ChecklistView from './components/ChecklistView';
import ManagerWorkspace from './components/ManagerWorkspace';
import TeamView from './components/TeamView';
import SalesView from './components/SalesView';

const App: React.FC = () => {
  const currentYear = new Date().getFullYear();
  const currentMonthName = MONTHS[new Date().getMonth()];

  const [currentUser, setCurrentUser] = useState<User>({ id: 'ceo', name: 'Diretor Omega', role: UserRole.CEO });
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedMonth, setSelectedMonth] = useState(`${currentMonthName} ${currentYear}`);

  // Banco de Dados Mensal
  const [db, setDb] = useState<MonthlyData>(() => {
    const saved = localStorage.getItem('omega_db_v3');
    if (saved) return JSON.parse(saved);

    // Inicializa com o mês atual caso não exista
    return {
      [`${currentMonthName} ${currentYear}`]: {
        clients: INITIAL_CLIENTS,
        tasks: []
      }
    };
  });

  const [team, setTeam] = useState<User[]>(() => {
    const saved = localStorage.getItem('omega_team');
    return saved ? JSON.parse(saved) : [
      { id: 'ceo', name: 'Diretor Omega', role: UserRole.CEO },
      { id: 'm1', name: 'Ricardo Tráfego', role: UserRole.MANAGER },
      { id: 'm2', name: 'Amanda Ads', role: UserRole.MANAGER },
      { id: 'm3', name: 'Bruno Sales', role: UserRole.SALES, salesCount: 0, salesVolume: 0 }
    ];
  });

  useEffect(() => {
    localStorage.setItem('omega_db_v3', JSON.stringify(db));
    localStorage.setItem('omega_team', JSON.stringify(team));
  }, [db, team]);

  // Helpers para acessar dados do mês atual selecionado
  const currentData = db[selectedMonth] || { clients: [], tasks: [] };
  const clients = currentData.clients;
  const tasks = currentData.tasks;

  const updateCurrentMonthData = (updates: Partial<{ clients: Client[], tasks: Task[] }>) => {
    setDb(prev => ({
      ...prev,
      [selectedMonth]: {
        ...currentData,
        ...updates
      }
    }));
  };

  const handleMonthChange = (month: string) => {
    // Se o mês selecionado não existe no DB, cria um novo baseado no anterior ou vazio
    if (!db[month]) {
      setDb(prev => ({
        ...prev,
        [month]: {
          clients: clients.map(c => ({ ...c, progress: 0, statusFlag: 'GREEN' })), // Reset progress para novo mês
          tasks: []
        }
      }));
    }
    setSelectedMonth(month);
  };

  const handleUpdateRole = (userId: string, newRole: UserRole) => {
    setTeam(prev => prev.map(u => u.id === userId ? { ...u, role: newRole } : u));
    if (currentUser.id === userId) setCurrentUser(prev => ({ ...prev, role: newRole }));
  };

  const handleAssignManager = (clientId: string, managerId: string) => {
    updateCurrentMonthData({
      clients: clients.map(c => c.id === clientId ? { ...c, managerId } : c)
    });
  };

  const handleUpdateNotes = (clientId: string, notes: string) => {
    updateCurrentMonthData({
      clients: clients.map(c => c.id === clientId ? { ...c, notes } : c)
    });
  };

  const handleUpdateStatusFlag = (clientId: string, flag: ClientStatus) => {
    updateCurrentMonthData({
      clients: clients.map(c => c.id === clientId ? { ...c, statusFlag: flag } : c)
    });
  };

  const handleAddTask = (taskData: Partial<Task>) => {
    const newTask = { 
      ...taskData, 
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString()
    } as Task;
    updateCurrentMonthData({ tasks: [newTask, ...tasks] });
  };

  const handleRemoveTask = (id: string) => {
    updateCurrentMonthData({ tasks: tasks.filter(t => t.id !== id) });
  };

  const handleToggleTask = (id: string) => {
    updateCurrentMonthData({
      tasks: tasks.map(t => t.id === id ? { ...t, status: t.status === 'COMPLETED' ? 'PENDING' : 'COMPLETED' } : t)
    });
  };

  const handleSwitchUser = (userId: string) => {
    const user = team.find(u => u.id === userId) || { id: 'ceo', name: 'Diretor Omega', role: UserRole.CEO };
    setCurrentUser(user);
    setActiveTab('dashboard');
  };

  const allAvailableMonths = MONTHS.map(m => `${m} ${currentYear}`);

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <Dashboard 
            clients={clients} 
            tasks={tasks} 
            currentMonth={selectedMonth} 
            months={allAvailableMonths}
            onMonthChange={handleMonthChange}
          />
        );
      case 'my-workspace':
        return (
          <ManagerWorkspace 
            managerId={currentUser.id} 
            clients={clients} 
            tasks={tasks} 
            onToggleTask={handleToggleTask}
            onUpdateNotes={handleUpdateNotes}
            onUpdateStatusFlag={handleUpdateStatusFlag}
          />
        );
      case 'commercial':
        return <SalesView goal={{ monthlyTarget: 100000, currentValue: 43500, totalSales: 20 }} team={team} currentUser={currentUser} />;
      case 'clients':
        return <SquadsView clients={clients} onAssignManager={handleAssignManager} />;
      case 'checklists':
        return <ChecklistView tasks={tasks} onAddTask={handleAddTask} onRemoveTask={handleRemoveTask} />;
      case 'team':
        return <TeamView team={team} onUpdateRole={handleUpdateRole} />;
      case 'notes':
        return (
           <div className="space-y-6 max-w-[1400px] mx-auto">
             <h2 className="text-2xl font-bold text-white uppercase italic tracking-tighter">Wiki & Notas Técnicas</h2>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {clients.map(c => (
                  <div key={c.id} className="bg-[#111] border border-white/5 p-8 rounded-[32px] space-y-4 group">
                    <h4 className="font-bold text-white uppercase text-xs tracking-widest group-hover:text-[#14b8a6] transition-colors">{c.name}</h4>
                    <textarea 
                      value={c.notes || ''}
                      onChange={(e) => handleUpdateNotes(c.id, e.target.value)}
                      placeholder="Anote detalhes técnicos aqui..."
                      className="w-full bg-black border border-white/5 rounded-2xl p-6 text-xs text-gray-400 min-h-[180px] outline-none focus:border-[#14b8a6]/30 transition-all resize-none shadow-inner"
                    />
                  </div>
                ))}
             </div>
           </div>
        );
      default:
        return <div className="p-10 text-center opacity-30 italic">Acesso Restrito.</div>;
    }
  };

  return (
    <div className="flex h-screen bg-[#0a0a0a] text-gray-300 overflow-hidden font-inter selection:bg-[#14b8a6] selection:text-black">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        currentUser={currentUser} 
        onSwitchUser={handleSwitchUser}
      />

      <main className="flex-1 flex flex-col h-full overflow-hidden relative">
        <div className="flex-1 overflow-y-auto p-12 custom-scrollbar z-0">
          {renderContent()}
        </div>

        <div className="fixed top-[-100px] right-[-100px] w-[700px] h-[700px] bg-[#14b8a6]/5 blur-[180px] rounded-full pointer-events-none -z-10"></div>
      </main>
    </div>
  );
};

