interface SalesViewProps {
  goal: SalesGoal;
  team: User[];
  currentUser: User;
  onUpdateGoal: (updates: Partial<SalesGoal>) => void;
  onRegisterSale: (userId: string, value: number) => void;
  onUpdateUserGoal: (userId: string, personalGoal: number, superGoal: number) => void;
}

const SalesView: React.FC<SalesViewProps> = ({ 
  goal, team, currentUser, onUpdateGoal, onRegisterSale, onUpdateUserGoal 
}) => {
  const [celebration, setCelebration] = useState<{ name: string; value: number } | null>(null);
  const [isEditingGoal, setIsEditingGoal] = useState(false);
  const [saleValue, setSaleValue] = useState<string>('');
  const [selectedSeller, setSelectedSeller] = useState<string>('');

  const sellers = team.filter(u => u.role === UserRole.SALES).sort((a, b) => (b.salesVolume || 0) - (a.salesVolume || 0));
  const progressPercent = Math.min(100, Math.round((goal.currentValue / goal.monthlyTarget) * 100));

  // Trigger celebration logic
  const handleConfirmSale = () => {
    const val = parseFloat(saleValue);
    if (!selectedSeller || isNaN(val)) return;

    const seller = team.find(u => u.id === selectedSeller);
    if (seller) {
      setCelebration({ name: seller.name, value: val });
      onRegisterSale(selectedSeller, val);
      setSaleValue('');

      // Auto-hide celebration after 5 seconds
      setTimeout(() => setCelebration(null), 5000);
    }
  };

  const getSellerStatusClass = (seller: User) => {
    const vol = seller.salesVolume || 0;
    const goal = seller.personalGoal || 10000;
    const superGoal = seller.superGoal || 15000;

    if (vol >= superGoal) return 'animate-gold-shine border-amber-400';
    if (vol >= goal) return 'border-green-500 bg-green-500/5';
    if (vol >= goal * 0.5) return 'animate-pulse-yellow border-yellow-500/50 bg-yellow-500/5';
    return 'border-red-500/30 bg-red-500/5';
  };

  const getStatusBadge = (seller: User) => {
    const vol = seller.salesVolume || 0;
    const goal = seller.personalGoal || 10000;
    const superGoal = seller.superGoal || 15000;

    if (vol >= superGoal) return <span className="text-[9px] font-black text-amber-400 uppercase tracking-widest">★ SUPER META ★</span>;
    if (vol >= goal) return <span className="text-[9px] font-black text-green-500 uppercase tracking-widest">META BATIDA</span>;
    if (vol >= goal * 0.5) return <span className="text-[9px] font-black text-yellow-500 uppercase tracking-widest">EM PROGRESSO</span>;
    return <span className="text-[9px] font-black text-red-500 uppercase tracking-widest">CRÍTICO</span>;
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 max-w-[1400px] mx-auto relative">

