              <Bell className="w-48 h-48 text-amber-400 animate-bell drop-shadow-[0_0_50px_rgba(251,191,36,0.5)]" />
              <div className="absolute inset-0 animate-ping bg-amber-400/20 rounded-full"></div>
            </div>
            <div className="space-y-2">
              <h2 className="text-6xl font-black text-white uppercase tracking-tighter italic">VENDA FECHADA!</h2>
