              <p className="text-5xl font-black text-white">R$ {celebration.value.toLocaleString()}</p>
            </div>
            <button onClick={() => setCelebration(null)} className="px-8 py-3 bg-white text-black font-black rounded-full hover:scale-110 transition-transform">FECHAR</button>
          </div>
        </div>
      )}

      <header className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Target className="w-6 h-6 text-[#14b8a6]" />
          <div>
            <h2 className="text-3xl font-bold text-white tracking-tight">Comercial & Performance</h2>
            <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Foco em fechamento e expansão</p>
          </div>
        </div>
        <div className="flex gap-4">
          <button 
            onClick={() => setIsEditingGoal(!isEditingGoal)}
            className="bg-white/5 border border-white/10 px-6 py-2 rounded-2xl text-[10px] font-black text-white uppercase hover:bg-white/10 transition-colors flex items-center gap-2"
          >
            <Edit2 className="w-3 h-3" /> Ajustar Metas
          </button>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Painel de Controle de Metas e Lançamento */}
        <div className="lg:col-span-2 space-y-6">

          {/* Form de Registro de Venda */}
          <div className="bg-[#111] border border-white/5 rounded-[32px] p-8 space-y-6">
