                <TrendingUp className="w-[300px] h-[300px]" />
             </div>

             <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-10">
                <div className="space-y-6 flex-1">
                  <div>
                    <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">Volume Total do Mês</p>
                    <h3 className="text-5xl font-black text-white">R$ {goal.currentValue.toLocaleString()}<span className="text-[#14b8a6] text-xl font-medium ml-2">/ R$ {goal.monthlyTarget.toLocaleString()}</span></h3>
                  </div>

                  <div className="w-full h-4 bg-white/5 rounded-full overflow-hidden">
                    <div className="h-full bg-gradient-to-r from-[#14b8a6] to-blue-500 transition-all duration-1000" style={{ width: `${progressPercent}%` }}></div>
                  </div>

                  {isEditingGoal && (
                    <div className="grid grid-cols-2 gap-4 animate-in slide-in-from-top-2">
                      <div className="space-y-1">
                        <label className="text-[9px] font-black text-gray-600 uppercase">Meta Global</label>
                        <input 
                          type="number" 
                          defaultValue={goal.monthlyTarget}
                          onBlur={(e) => onUpdateGoal({ monthlyTarget: parseFloat(e.target.value) })}
                          className="w-full bg-black border border-white/5 rounded-lg px-3 py-2 text-xs text-white"
                        />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[9px] font-black text-gray-600 uppercase">Super Meta Global</label>
                        <input 
                          type="number" 
                          defaultValue={goal.monthlySuperTarget}
                          onBlur={(e) => onUpdateGoal({ monthlySuperTarget: parseFloat(e.target.value) })}
                          className="w-full bg-black border border-white/5 rounded-lg px-3 py-2 text-xs text-white"
                        />
                      </div>
                    </div>
                  )}

                  <div className="grid grid-cols-2 gap-4">
                    <div className="bg-black/40 p-4 rounded-2xl border border-white/5">
                      <p className="text-[10px] font-bold text-gray-500 uppercase">Contratos Fechados</p>
                      <p className="text-2xl font-black text-white">{goal.totalSales}</p>
                    </div>
                    <div className="bg-black/40 p-4 rounded-2xl border border-white/5">
                      <p className="text-[10px] font-bold text-gray-500 uppercase">Meta Batida</p>
                      <p className="text-2xl font-black text-white">{progressPercent}%</p>
                    </div>
                  </div>
                </div>
             </div>
          </div>
        </div>

        {/* Ranking Dinâmico e Colorido */}
        <div className="bg-[#111] border border-white/5 rounded-[32px] p-8 space-y-6">
          <h4 className="flex items-center gap-2 text-lg font-bold text-white uppercase italic tracking-tighter">
            <Trophy className="w-5 h-5 text-yellow-500" /> Ranking Top Sellers
          </h4>
          <div className="space-y-4 max-h-[600px] overflow-y-auto pr-2 custom-scrollbar">
            {sellers.map((seller, index) => (
              <div key={seller.id} className={`flex flex-col p-5 rounded-2xl border transition-all duration-500 ${getSellerStatusClass(seller)}`}>
                <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center gap-3">
                    <span className={`w-6 h-6 rounded-lg flex items-center justify-center text-[10px] font-black ${index === 0 ? 'bg-amber-400 text-black' : 'bg-white/10 text-white'}`}>
                      {index + 1}
                    </span>
                    <div>
                      <p className="text-sm font-bold text-white uppercase tracking-tighter">{seller.name}</p>
                      {getStatusBadge(seller)}
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-xs font-black text-white">R$ {(seller.salesVolume || 0).toLocaleString()}</p>
                    <p className="text-[9px] text-gray-500 font-bold">{seller.salesCount || 0} VENDAS</p>
                  </div>
                </div>

                {isEditingGoal ? (
                  <div className="grid grid-cols-2 gap-2 mt-2 pt-2 border-t border-white/5 animate-in fade-in">
                    <div className="space-y-1">
                      <label className="text-[8px] font-black text-gray-600 uppercase">Meta</label>
                      <input 
                        type="number"
                        defaultValue={seller.personalGoal || 10000}
                        onBlur={(e) => onUpdateUserGoal(seller.id, parseFloat(e.target.value), seller.superGoal || 15000)}
                        className="w-full bg-black/60 border border-white/10 rounded px-2 py-1 text-[10px] text-teal-400"
                      />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[8px] font-black text-gray-600 uppercase">Super</label>
                      <input 
                        type="number"
                        defaultValue={seller.superGoal || 15000}
                        onBlur={(e) => onUpdateUserGoal(seller.id, seller.personalGoal || 10000, parseFloat(e.target.value))}
                        className="w-full bg-black/60 border border-white/10 rounded px-2 py-1 text-[10px] text-amber-400"
                      />
                    </div>
                  </div>
                ) : (
                  <div className="w-full h-1 bg-white/5 rounded-full overflow-hidden mt-2">
                    <div 
                      className={`h-full transition-all duration-1000 ${volPercent(seller) >= 100 ? 'bg-amber-400' : 'bg-[#14b8a6]'}`} 
                      style={{ width: `${Math.min(100, volPercent(seller))}%` }}
                    ></div>
                  </div>
                )}
              </div>
            ))}
            {sellers.length === 0 && <p className="text-center text-gray-600 text-xs py-10 italic">Nenhum vendedor ativo.</p>}
          </div>
        </div>
      </div>
    </div>
  );
};

function volPercent(seller: User) {
  return ((seller.salesVolume || 0) / (seller.personalGoal || 10000)) * 100;
}

export default SalesView;

import React, { useState, useEffect } from 'react';
import { UserRole, Client, Task, User, MonthlyData, ClientStatus, SalesGoal } from './types';
import { INITIAL_CLIENTS, NAVIGATION_ITEMS, MANAGERS, MONTHS } from './constants';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import SquadsView from './components/SquadsView';
import ChecklistView from './components/ChecklistView';
import ManagerWorkspace from './components/ManagerWorkspace';
import TeamView from './components/TeamView';
import SalesView from './components/SalesView';

const App: React.FC = () => {
  const currentYear = new Date().getFullYear();
  const currentMonthName = MONTHS[new Date().getMonth()];

  const [currentUser, setCurrentUser] = useState<User>({ id: 'ceo', name: 'Diretor Omega', role: UserRole.CEO });
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedMonth, setSelectedMonth] = useState(`${currentMonthName} ${currentYear}`);

  // Banco de Dados Mensal
  const [db, setDb] = useState<MonthlyData>(() => {
    const saved = localStorage.getItem('omega_db_v4');
    if (saved) return JSON.parse(saved);

    return {
      [`${currentMonthName} ${currentYear}`]: {
        clients: INITIAL_CLIENTS,
        tasks: [],
        salesGoal: {
          monthlyTarget: 100000,
          monthlySuperTarget: 150000,
          currentValue: 0,
          totalSales: 0
        }
      }
    };
  });

  const [team, setTeam] = useState<User[]>(() => {
    const saved = localStorage.getItem('omega_team_v2');
    return saved ? JSON.parse(saved) : [
      { id: 'ceo', name: 'Diretor Omega', role: UserRole.CEO },
      { id: 'm1', name: 'Ricardo Tráfego', role: UserRole.MANAGER },
      { id: 'm2', name: 'Amanda Ads', role: UserRole.MANAGER },
      { id: 'm3', name: 'Bruno Sales', role: UserRole.SALES, salesCount: 0, salesVolume: 0, personalGoal: 20000, superGoal: 35000 },
      { id: 'm4', name: 'Lucas Sales', role: UserRole.SALES, salesCount: 0, salesVolume: 0, personalGoal: 25000, superGoal: 40000 }
    ];
  });

  useEffect(() => {
    localStorage.setItem('omega_db_v4', JSON.stringify(db));
    localStorage.setItem('omega_team_v2', JSON.stringify(team));
  }, [db, team]);

  const currentData = db[selectedMonth] || { clients: [], tasks: [], salesGoal: { monthlyTarget: 100000, monthlySuperTarget: 150000, currentValue: 0, totalSales: 0 } };

  const updateCurrentMonthData = (updates: Partial<{ clients: Client[], tasks: Task[], salesGoal: SalesGoal }>) => {
    setDb(prev => ({
      ...prev,
      [selectedMonth]: {
        ...currentData,
        ...updates
      }
    }));
  };

  const handleRegisterSale = (userId: string, value: number) => {
    // Atualiza o volume do vendedor no time
    setTeam(prev => prev.map(u => u.id === userId ? {
      ...u,
      salesCount: (u.salesCount || 0) + 1,
      salesVolume: (u.salesVolume || 0) + value
    } : u));

    // Atualiza o volume global do mês
    updateCurrentMonthData({
      salesGoal: {
        ...currentData.salesGoal,
        currentValue: currentData.salesGoal.currentValue + value,
        totalSales: currentData.salesGoal.totalSales + 1
      }
    });
  };

  const handleUpdateGoal = (updates: Partial<SalesGoal>) => {
    updateCurrentMonthData({
      salesGoal: { ...currentData.salesGoal, ...updates }
    });
  };

  const handleUpdateUserGoal = (userId: string, personalGoal: number, superGoal: number) => {
    setTeam(prev => prev.map(u => u.id === userId ? { ...u, personalGoal, superGoal } : u));
  };

  const handleMonthChange = (month: string) => {
    if (!db[month]) {
      setDb(prev => ({
        ...prev,
        [month]: {
          clients: currentData.clients.map(c => ({ ...c, progress: 0, statusFlag: 'GREEN' })),
          tasks: [],
          salesGoal: { monthlyTarget: 100000, monthlySuperTarget: 150000, currentValue: 0, totalSales: 0 }
        }
      }));
    }
    setSelectedMonth(month);
  };

  const handleUpdateRole = (userId: string, newRole: UserRole) => {
    setTeam(prev => prev.map(u => u.id === userId ? { ...u, role: newRole } : u));
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard clients={currentData.clients} tasks={currentData.tasks} currentMonth={selectedMonth} months={MONTHS.map(m => `${m} ${currentYear}`)} onMonthChange={handleMonthChange} />;
      case 'commercial':
        return (
          <SalesView 
            goal={currentData.salesGoal} 
            team={team} 
            currentUser={currentUser} 
            onUpdateGoal={handleUpdateGoal}
            onRegisterSale={handleRegisterSale}
            onUpdateUserGoal={handleUpdateUserGoal}
          />
        );
      case 'my-workspace':
        return <ManagerWorkspace managerId={currentUser.id} clients={currentData.clients} tasks={currentData.tasks} onToggleTask={(id) => updateCurrentMonthData({ tasks: currentData.tasks.map(t => t.id === id ? { ...t, status: t.status === 'COMPLETED' ? 'PENDING' : 'COMPLETED' } : t) })} onUpdateNotes={(id, n) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === id ? { ...c, notes: n } : c) })} onUpdateStatusFlag={(id, f) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === id ? { ...c, statusFlag: f } : c) })} />;
      case 'clients':
        return <SquadsView clients={currentData.clients} onAssignManager={(cid, mid) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === cid ? { ...c, managerId: mid } : c) })} />;
      case 'checklists':
        return <ChecklistView tasks={currentData.tasks} onAddTask={(t) => updateCurrentMonthData({ tasks: [{ ...t, id: Math.random().toString(36).substr(2, 9), createdAt: new Date().toISOString() } as Task, ...currentData.tasks] })} onRemoveTask={(id) => updateCurrentMonthData({ tasks: currentData.tasks.filter(t => t.id !== id) })} />;
      case 'team':
        return <TeamView team={team} onUpdateRole={handleUpdateRole} />;
      default:
        return <div className="p-10 text-center opacity-30 italic">Em desenvolvimento.</div>;
    }
  };

  return (
    <div className="flex h-screen bg-[#0a0a0a] text-gray-300 overflow-hidden font-inter selection:bg-[#14b8a6] selection:text-black">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} currentUser={currentUser} onSwitchUser={(id) => { const u = team.find(x => x.id === id); if(u) setCurrentUser(u); setActiveTab('dashboard'); }} />
      <main className="flex-1 flex flex-col h-full overflow-hidden relative">
        <div className="flex-1 overflow-y-auto p-12 custom-scrollbar z-0">
          {renderContent()}
        </div>
        <div className="fixed top-[-100px] right-[-100px] w-[700px] h-[700px] bg-[#14b8a6]/5 blur-[180px] rounded-full pointer-events-none -z-10"></div>
      </main>
    </div>
  );
};

