import React, { useState } from 'react';
import { SalesGoal, User, UserRole } from '../types';
import { Target, TrendingUp, Trophy, Bell, Plus, Edit2, DollarSign, Link, Clipboard, StickyNote, CheckCircle2 } from 'lucide-react';

interface SalesViewProps {
  goal: SalesGoal;
  team: User[];
  currentUser: User;
  onUpdateGoal: (updates: Partial<SalesGoal>) => void;
  onRegisterSale: (userId: string, value: number) => void;
  onUpdateUserGoal: (userId: string, personalGoal: number, superGoal: number) => void;
}

const SalesView: React.FC<SalesViewProps> = ({ 
  goal, team, currentUser, onUpdateGoal, onRegisterSale, onUpdateUserGoal 
}) => {
  const [celebration, setCelebration] = useState<{ name: string; value: number } | null>(null);
  const [isEditingGoal, setIsEditingGoal] = useState(false);
  const [saleValue, setSaleValue] = useState<string>('');
  const [copied, setCopied] = useState(false);

  const isCEO = currentUser.role === UserRole.CEO;
  const isSales = currentUser.role === UserRole.SALES;

  const sellers = team.filter(u => u.role === UserRole.SALES).sort((a, b) => (b.salesVolume || 0) - (a.salesVolume || 0));
  const myData = team.find(u => u.id === currentUser.id);
  const progressPercent = Math.min(100, Math.round((goal.currentValue / goal.monthlyTarget) * 100));

  const handleConfirmSale = () => {
    const val = parseFloat(saleValue);
    if (isNaN(val) || val <= 0) return;

    setCelebration({ name: currentUser.name, value: val });
    onRegisterSale(currentUser.id, val);
    setSaleValue('');
    setTimeout(() => setCelebration(null), 5000);
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(goal.contractFormUrl);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const getSellerStatusClass = (seller: User) => {
    const vol = seller.salesVolume || 0;
    const g = seller.personalGoal || 10000;
    const sg = seller.superGoal || 15000;
    if (vol >= sg) return 'animate-gold-shine border-amber-400';
    if (vol >= g) return 'border-green-500 bg-green-500/5';
    if (vol >= g * 0.5) return 'animate-pulse-yellow border-yellow-500/50 bg-yellow-500/5';
    return 'border-red-500/30 bg-red-500/5';
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 max-w-[1400px] mx-auto relative pb-20">

      {/* Sino de Celebração (Visível para todos quando disparado) */}
      {celebration && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 backdrop-blur-xl animate-in fade-in zoom-in duration-300">
          <div className="text-center space-y-8">
            <Bell className="w-48 h-48 text-amber-400 animate-bell mx-auto drop-shadow-[0_0_50px_rgba(251,191,36,0.6)]" />
            <div className="space-y-2">
              <h2 className="text-6xl font-black text-white uppercase tracking-tighter italic">VENDA FECHADA!</h2>
              <p className="text-3xl font-bold text-[#14b8a6] uppercase">{celebration.name}</p>
              <p className="text-5xl font-black text-white">R$ {celebration.value.toLocaleString()}</p>
            </div>
            <button onClick={() => setCelebration(null)} className="px-12 py-4 bg-white text-black font-black rounded-full hover:scale-110 transition-transform uppercase tracking-widest text-sm">Continuar Voando</button>
          </div>
        </div>
      )}

      <header className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Target className="w-6 h-6 text-[#14b8a6]" />
          <div>
            <h2 className="text-3xl font-bold text-white tracking-tight uppercase italic">Setor Comercial</h2>
            <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Omega Performance System</p>
          </div>
        </div>

        {isCEO && (
          <button 
            onClick={() => setIsEditingGoal(!isEditingGoal)}
            className="bg-white/5 border border-white/10 px-6 py-2 rounded-2xl text-[10px] font-black text-white uppercase hover:bg-white/10 transition-colors flex items-center gap-2"
          >
            <Edit2 className="w-3 h-3" /> Ajustar Metas e Configurações
          </button>
        )}
      </header>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">

        <div className="xl:col-span-2 space-y-8">

          {/* ÁREA DO VENDEDOR: LANÇAMENTO E ONBOARDING */}
          {isSales && (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Card de Lançamento */}
              <div className="bg-[#111] border border-white/5 rounded-[32px] p-8 space-y-6">
                <h4 className="text-xs font-black text-white uppercase tracking-widest flex items-center gap-2">
                  <DollarSign className="w-4 h-4 text-[#14b8a6]" /> Registrar Venda
                </h4>
                <div className="space-y-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-gray-600 uppercase">Valor do Contrato Fechado</label>
                    <input 
                      type="number"
                      value={saleValue}
                      onChange={(e) => setSaleValue(e.target.value)}
                      placeholder="R$ 0,00"
                      className="w-full bg-black border border-white/10 rounded-2xl px-5 py-4 text-lg font-black text-white outline-none focus:border-[#14b8a6] transition-all"
                    />
                  </div>
                  <button 
                    onClick={handleConfirmSale}
                    className="w-full bg-[#14b8a6] text-black py-5 rounded-2xl font-black text-sm hover:scale-[1.02] transition-transform flex items-center justify-center gap-3 uppercase shadow-[0_10px_30px_rgba(20,184,166,0.2)]"
                  >
                    <Plus className="w-5 h-5" /> Confirmar e Notificar Time
                  </button>
                </div>
              </div>

              {/* Card de Onboarding (Link do Formulário) */}
              <div className="bg-[#111] border border-white/5 rounded-[32px] p-8 space-y-6 flex flex-col justify-between">
                <div>
                  <h4 className="text-xs font-black text-white uppercase tracking-widest flex items-center gap-2">
                    <Link className="w-4 h-4 text-blue-400" /> Onboarding de Cliente
                  </h4>
                  <p className="text-xs text-gray-500 mt-2">Mande este link para o cliente logo após o fechamento para coletar os dados do contrato.</p>
                </div>

                <div className="space-y-4">
                  <div className="bg-black/50 border border-white/5 rounded-2xl p-4 flex items-center justify-between">
                    <span className="text-[10px] text-gray-400 font-mono truncate mr-4">{goal.contractFormUrl || 'Link não configurado'}</span>
                    <button 
                      onClick={copyToClipboard}
                      className="p-3 bg-white/5 hover:bg-white/10 rounded-xl text-white transition-all"
                    >
                      {copied ? <CheckCircle2 className="w-4 h-4 text-green-500" /> : <Clipboard className="w-4 h-4" />}
                    </button>
                  </div>
                  <a 
                    href={goal.contractFormUrl} 
                    target="_blank" 
                    rel="noreferrer"
                    className="w-full bg-blue-500/10 text-blue-400 py-3 rounded-xl font-bold text-xs hover:bg-blue-500/20 transition-all text-center flex items-center justify-center gap-2"
                  >
                    TESTAR LINK DO FORMULÁRIO
                  </a>
                </div>
              </div>
            </div>
          )}

          {/* ÁREA DO CEO: AJUSTES DE CONFIGURAÇÃO */}
          {isCEO && isEditingGoal && (
            <div className="bg-[#111] border border-teal-500/30 rounded-[32px] p-8 space-y-6 animate-in slide-in-from-top-4">
              <h4 className="text-xs font-black text-white uppercase tracking-widest flex items-center gap-2">
                <Edit2 className="w-4 h-4 text-teal-500" /> Painel de Configurações Comerciais (Diretoria)
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-600 uppercase">Meta Global (R$)</label>
                  <input 
                    type="number"
                    defaultValue={goal.monthlyTarget}
                    onBlur={(e) => onUpdateGoal({ monthlyTarget: parseFloat(e.target.value) })}
                    className="w-full bg-black border border-white/10 rounded-xl px-4 py-3 text-sm text-white"
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-600 uppercase">Super Meta Global (R$)</label>
                  <input 
                    type="number"
                    defaultValue={goal.monthlySuperTarget}
