                          {seller.name} {seller.id === currentUser.id ? '(VOCÊ)' : ''}
                        </p>
                        <div className="flex items-center gap-2">
                           {getSellerStatusBadge(seller)}
                        </div>
                      </div>
                    </div>
                    <div className="text-right">
                      <p className="text-sm font-black text-white">R$ {(seller.salesVolume || 0).toLocaleString()}</p>
                      <p className="text-[9px] text-gray-500 font-bold uppercase">{seller.salesCount || 0} FECHAMENTOS</p>
                    </div>
                  </div>

                  {/* Edição de Meta Individual (Apenas CEO) */}
                  {isCEO && isEditingGoal ? (
                    <div className="grid grid-cols-2 gap-3 mt-4 pt-4 border-t border-white/5">
                      <div className="space-y-1">
                        <label className="text-[8px] font-black text-gray-600 uppercase">Meta (R$)</label>
                        <input 
                          type="number"
                          defaultValue={seller.personalGoal || 10000}
                          onBlur={(e) => onUpdateUserGoal(seller.id, parseFloat(e.target.value), seller.superGoal || 15000)}
                          className="w-full bg-black/60 border border-white/10 rounded-lg px-3 py-2 text-xs text-teal-400"
                        />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[8px] font-black text-gray-600 uppercase">Super Meta (R$)</label>
                        <input 
                          type="number"
                          defaultValue={seller.superGoal || 15000}
                          onBlur={(e) => onUpdateUserGoal(seller.id, seller.personalGoal || 10000, parseFloat(e.target.value))}
                          className="w-full bg-black/60 border border-white/10 rounded-lg px-3 py-2 text-xs text-amber-400"
                        />
                      </div>
                    </div>
                  ) : (
                    <div className="space-y-2 mt-2">
                       <div className="flex justify-between text-[8px] font-black text-gray-600 uppercase tracking-widest">
                         <span>Progresso da Meta</span>
                         <span>{Math.min(100, Math.round(((seller.salesVolume || 0) / (seller.personalGoal || 10000)) * 100))}%</span>
                       </div>
                       <div className="w-full h-1 bg-white/5 rounded-full overflow-hidden">
                        <div 
                          className={`h-full transition-all duration-1000 ${volPercent(seller) >= 100 ? 'bg-amber-400' : 'bg-[#14b8a6]'}`} 
                          style={{ width: `${Math.min(100, volPercent(seller))}%` }}
                        ></div>
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>

            {/* Meta Pessoal do Vendedor Logado */}
            {isSales && myData && (
              <div className="mt-6 p-6 bg-[#14b8a6]/10 border border-[#14b8a6]/30 rounded-2xl">
                <p className="text-[10px] font-black text-[#14b8a6] uppercase tracking-widest mb-2 text-center">Sua Meta do Mês</p>
                <div className="flex justify-between items-baseline">
                   <span className="text-2xl font-black text-white">R$ {(myData.salesVolume || 0).toLocaleString()}</span>
                   <span className="text-xs text-gray-500 font-bold">/ R$ {(myData.personalGoal || 10000).toLocaleString()}</span>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

function volPercent(seller: User) {
  return ((seller.salesVolume || 0) / (seller.personalGoal || 10000)) * 100;
}

function getSellerStatusBadge(seller: User) {
  const vol = seller.salesVolume || 0;
  const goal = seller.personalGoal || 10000;
  const superGoal = seller.superGoal || 15000;
  if (vol >= superGoal) return <span className="text-[8px] font-black text-amber-400 uppercase tracking-widest">★ SHINE ★</span>;
  if (vol >= goal) return <span className="text-[8px] font-black text-green-500 uppercase tracking-widest">BATIDA</span>;
  if (vol >= goal * 0.5) return <span className="text-[8px] font-black text-yellow-500 uppercase tracking-widest">PULSE</span>;
  return <span className="text-[8px] font-black text-red-500 uppercase tracking-widest">CRÍTICO</span>;
}

