import React, { useState, useEffect } from 'react';
import { UserRole, Client, Task, User, MonthlyData, ClientStatus, SalesGoal } from './types';
import { INITIAL_CLIENTS, NAVIGATION_ITEMS, MANAGERS, MONTHS } from './constants';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import SquadsView from './components/SquadsView';
import ChecklistView from './components/ChecklistView';
import ManagerWorkspace from './components/ManagerWorkspace';
import TeamView from './components/TeamView';
import SalesView from './components/SalesView';

const App: React.FC = () => {
  const currentYear = new Date().getFullYear();
  const currentMonthName = MONTHS[new Date().getMonth()];

  const [currentUser, setCurrentUser] = useState<User>({ id: 'ceo', name: 'Diretor Omega', role: UserRole.CEO });
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedMonth, setSelectedMonth] = useState(`${currentMonthName} ${currentYear}`);

  // Banco de Dados Mensal v5
  const [db, setDb] = useState<MonthlyData>(() => {
    const saved = localStorage.getItem('omega_db_v5');
    if (saved) return JSON.parse(saved);

    return {
      [`${currentMonthName} ${currentYear}`]: {
        clients: INITIAL_CLIENTS,
        tasks: [],
        salesGoal: {
          monthlyTarget: 100000,
          monthlySuperTarget: 150000,
          currentValue: 0,
          totalSales: 0,
          contractFormUrl: 'https://seulink.com/formulario-onboarding',
          salesNotes: ''
        }
      }
    };
  });

  const [team, setTeam] = useState<User[]>(() => {
    const saved = localStorage.getItem('omega_team_v3');
    return saved ? JSON.parse(saved) : [
      { id: 'ceo', name: 'Diretor Omega', role: UserRole.CEO },
      { id: 'm1', name: 'Ricardo Tráfego', role: UserRole.MANAGER },
      { id: 'm2', name: 'Amanda Ads', role: UserRole.MANAGER },
      { id: 'm3', name: 'Bruno Sales', role: UserRole.SALES, salesCount: 0, salesVolume: 0, personalGoal: 20000, superGoal: 35000 },
      { id: 'm4', name: 'Lucas Sales', role: UserRole.SALES, salesCount: 0, salesVolume: 0, personalGoal: 25000, superGoal: 40000 }
    ];
  });

  useEffect(() => {
    localStorage.setItem('omega_db_v5', JSON.stringify(db));
    localStorage.setItem('omega_team_v3', JSON.stringify(team));
  }, [db, team]);

  const currentData = db[selectedMonth] || { 
    clients: [], 
    tasks: [], 
    salesGoal: { monthlyTarget: 100000, monthlySuperTarget: 150000, currentValue: 0, totalSales: 0, contractFormUrl: '', salesNotes: '' } 
  };

  const updateCurrentMonthData = (updates: Partial<{ clients: Client[], tasks: Task[], salesGoal: SalesGoal }>) => {
    setDb(prev => ({
      ...prev,
      [selectedMonth]: {
        ...currentData,
        ...updates
      }
    }));
  };

  const handleRegisterSale = (userId: string, value: number) => {
    setTeam(prev => prev.map(u => u.id === userId ? {
      ...u,
      salesCount: (u.salesCount || 0) + 1,
      salesVolume: (u.salesVolume || 0) + value
    } : u));

    updateCurrentMonthData({
      salesGoal: {
        ...currentData.salesGoal,
        currentValue: currentData.salesGoal.currentValue + value,
        totalSales: currentData.salesGoal.totalSales + 1
      }
    });
  };

  const handleUpdateGoal = (updates: Partial<SalesGoal>) => {
    updateCurrentMonthData({
      salesGoal: { ...currentData.salesGoal, ...updates }
    });
  };

  const handleUpdateUserGoal = (userId: string, personalGoal: number, superGoal: number) => {
    setTeam(prev => prev.map(u => u.id === userId ? { ...u, personalGoal, superGoal } : u));
  };

  const handleMonthChange = (month: string) => {
    if (!db[month]) {
      setDb(prev => ({
        ...prev,
        [month]: {
          clients: currentData.clients.map(c => ({ ...c, progress: 0, statusFlag: 'GREEN' })),
          tasks: [],
          salesGoal: { ...currentData.salesGoal, currentValue: 0, totalSales: 0 }
        }
      }));
    }
    setSelectedMonth(month);
  };

  const handleUpdateRole = (userId: string, newRole: UserRole) => {
    setTeam(prev => prev.map(u => u.id === userId ? { ...u, role: newRole } : u));
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard clients={currentData.clients} tasks={currentData.tasks} currentMonth={selectedMonth} months={MONTHS.map(m => `${m} ${currentYear}`)} onMonthChange={handleMonthChange} />;
      case 'commercial':
        return (
          <SalesView 
            goal={currentData.salesGoal} 
            team={team} 
            currentUser={currentUser} 
            onUpdateGoal={handleUpdateGoal}
            onRegisterSale={handleRegisterSale}
            onUpdateUserGoal={handleUpdateUserGoal}
          />
        );
      case 'my-workspace':
        return <ManagerWorkspace managerId={currentUser.id} clients={currentData.clients} tasks={currentData.tasks} onToggleTask={(id) => updateCurrentMonthData({ tasks: currentData.tasks.map(t => t.id === id ? { ...t, status: t.status === 'COMPLETED' ? 'PENDING' : 'COMPLETED' } : t) })} onUpdateNotes={(id, n) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === id ? { ...c, notes: n } : c) })} onUpdateStatusFlag={(id, f) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === id ? { ...c, statusFlag: f } : c) })} />;
      case 'clients':
        return <SquadsView clients={currentData.clients} onAssignManager={(cid, mid) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === cid ? { ...c, managerId: mid } : c) })} />;
      case 'checklists':
        return <ChecklistView tasks={currentData.tasks} onAddTask={(t) => updateCurrentMonthData({ tasks: [{ ...t, id: Math.random().toString(36).substr(2, 9), createdAt: new Date().toISOString() } as Task, ...currentData.tasks] })} onRemoveTask={(id) => updateCurrentMonthData({ tasks: currentData.tasks.filter(t => t.id !== id) })} />;
      case 'team':
        return <TeamView team={team} onUpdateRole={handleUpdateRole} />;
      default:
        return <div className="p-10 text-center opacity-30 italic">Em desenvolvimento.</div>;
    }
  };

  return (
    <div className="flex h-screen bg-[#0a0a0a] text-gray-300 overflow-hidden font-inter selection:bg-[#14b8a6] selection:text-black">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} currentUser={currentUser} onSwitchUser={(id) => { const u = team.find(x => x.id === id); if(u) setCurrentUser(u); setActiveTab('dashboard'); }} />
      <main className="flex-1 flex flex-col h-full overflow-hidden relative">
        <div className="flex-1 overflow-y-auto p-12 custom-scrollbar z-0">
          {renderContent()}
        </div>
        <div className="fixed top-[-100px] right-[-100px] w-[700px] h-[700px] bg-[#14b8a6]/5 blur-[180px] rounded-full pointer-events-none -z-10"></div>
      </main>
    </div>
  );
};

export default App;

