import React, { useState, useEffect } from 'react';
import { UserRole, Client, Task, User, MonthlyData, ClientStatus, SalesGoal, ChatMessage, ClientHealth } from './types';
import { INITIAL_CLIENTS, NAVIGATION_ITEMS, MANAGERS, MONTHS } from './constants';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import SquadsView from './components/SquadsView';
import ChecklistView from './components/ChecklistView';
import ManagerWorkspace from './components/ManagerWorkspace';
import TeamView from './components/TeamView';
import SalesView from './components/SalesView';
import { Send, Hash } from 'lucide-react';

const App: React.FC = () => {
  const currentYear = new Date().getFullYear();
  const currentMonthName = MONTHS[new Date().getMonth()];

  const [currentUser, setCurrentUser] = useState<User>({ id: 'ceo', name: 'Diretor Omega', role: UserRole.CEO });
  const [activeTab, setActiveTab] = useState('commercial');
  const [selectedMonth, setSelectedMonth] = useState(`${currentMonthName} ${currentYear}`);
  const [chatInput, setChatInput] = useState('');

  const [db, setDb] = useState<MonthlyData>(() => {
    const saved = localStorage.getItem('omega_db_v6');
    if (saved) return JSON.parse(saved);

    return {
      [`${currentMonthName} ${currentYear}`]: {
        clients: INITIAL_CLIENTS,
        tasks: [
          { id: 'st1', title: 'Follow-up de leads frio', assignedTo: 'ALL', status: 'PENDING', priority: 'HIGH', type: 'WEEKLY', createdAt: '' },
          { id: 'st2', title: 'Atualizar CRM com objeções', assignedTo: 'ALL', status: 'PENDING', priority: 'MEDIUM', type: 'ONCE', createdAt: '' }
        ],
        salesGoal: {
          monthlyTarget: 100000,
          monthlySuperTarget: 150000,
          currentValue: 0,
          totalSales: 0,
          contractFormUrl: 'https://seulink.com/onboarding',
          salesNotes: ''
        },
        chatMessages: []
      }
    };
  });

  const [team, setTeam] = useState<User[]>(() => {
    const saved = localStorage.getItem('omega_team_v4');
    return saved ? JSON.parse(saved) : [
      { id: 'ceo', name: 'Diretor Omega', role: UserRole.CEO },
      { id: 'm1', name: 'Ricardo Tráfego', role: UserRole.MANAGER },
      { id: 'm2', name: 'Amanda Ads', role: UserRole.MANAGER },
      { id: 'm3', name: 'Bruno Sales', role: UserRole.SALES, salesCount: 0, salesVolume: 0, personalGoal: 30000, superGoal: 50000 },
      { id: 'm4', name: 'Lucas Sales', role: UserRole.SALES, salesCount: 0, salesVolume: 0, personalGoal: 25000, superGoal: 45000 }
    ];
  });

  useEffect(() => {
    localStorage.setItem('omega_db_v6', JSON.stringify(db));
    localStorage.setItem('omega_team_v4', JSON.stringify(team));
  }, [db, team]);

  const currentData = db[selectedMonth] || { clients: [], tasks: [], salesGoal: { monthlyTarget: 100000, currentValue: 0, totalSales: 0, contractFormUrl: '', salesNotes: '' }, chatMessages: [] };

  const updateCurrentMonthData = (updates: Partial<MonthlyData[string]>) => {
    setDb(prev => ({
      ...prev,
      [selectedMonth]: { ...currentData, ...updates }
    }));
  };

  const handleRegisterSale = (userId: string, value: number, clientName: string) => {
    // 1. Atualiza time
    setTeam(prev => prev.map(u => u.id === userId ? {
      ...u,
      salesCount: (u.salesCount || 0) + 1,
      salesVolume: (u.salesVolume || 0) + value
    } : u));

    // 2. Cria o novo cliente para o operacional
    const newClient: Client = {
      id: Math.random().toString(36).substr(2, 9),
      name: clientName,
      industry: 'Novo Contrato',
      health: ClientHealth.STABLE,
      progress: 0,
      managerId: '', // Ainda sem gestor
      salesId: userId,
      contractValue: value,
      statusFlag: 'GREEN',
      notes: '',
      closingNotes: ''
    };

    updateCurrentMonthData({
      salesGoal: {
        ...currentData.salesGoal,
        currentValue: currentData.salesGoal.currentValue + value,
        totalSales: currentData.salesGoal.totalSales + 1
      },
      clients: [...currentData.clients, newClient]
    });
  };

  const handleSendChatMessage = () => {
    if (!chatInput.trim()) return;
    const newMessage: ChatMessage = {
      id: Date.now().toString(),
      senderId: currentUser.id,
      senderName: currentUser.name,
      text: chatInput,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    updateCurrentMonthData({ chatMessages: [...(currentData.chatMessages || []), newMessage] });
    setChatInput('');
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard clients={currentData.clients} tasks={currentData.tasks} currentMonth={selectedMonth} months={MONTHS.map(m => `${m} ${currentYear}`)} onMonthChange={setSelectedMonth} />;
      case 'commercial':
        return (
          <SalesView 
            goal={currentData.salesGoal} 
            team={team} 
            clients={currentData.clients}
            currentUser={currentUser} 
            onUpdateGoal={(u) => updateCurrentMonthData({ salesGoal: { ...currentData.salesGoal, ...u } })}
            onRegisterSale={handleRegisterSale}
            onUpdateUserGoal={(id, pg, sg) => setTeam(prev => prev.map(u => u.id === id ? { ...u, personalGoal: pg, superGoal: sg } : u))}
            onUpdateClientNotes={(cid, n) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === cid ? { ...c, closingNotes: n } : c) })}
          />
        );
      case 'chat':
        return (
          <div className="flex flex-col h-full max-w-[1000px] mx-auto animate-in fade-in duration-500">
            <header className="mb-8">
               <h2 className="text-3xl font-black text-white italic uppercase flex items-center gap-3">
                 <Hash className="w-8 h-8 text-teal-500" /> Comunicação do Time
               </h2>
               <p className="text-gray-500 text-sm mt-2 font-medium">Espaço para troca de experiências, dúvidas e motivação mútua.</p>
            </header>
            <div className="flex-1 bg-[#111] border border-white/5 rounded-[40px] flex flex-col overflow-hidden">
               <div className="flex-1 p-8 overflow-y-auto space-y-6 custom-scrollbar">
                  {currentData.chatMessages?.map(msg => (
                    <div key={msg.id} className={`flex flex-col ${msg.senderId === currentUser.id ? 'items-end' : 'items-start'}`}>
                       <div className="flex items-center gap-2 mb-1">
                          <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest">{msg.senderName}</span>
                          <span className="text-[9px] text-gray-700 font-bold">{msg.timestamp}</span>
                       </div>
                       <div className={`px-6 py-3 rounded-2xl text-sm max-w-[70%] ${msg.senderId === currentUser.id ? 'bg-[#14b8a6] text-black font-bold' : 'bg-white/5 text-white border border-white/5'}`}>
                          {msg.text}
                       </div>
                    </div>
                  ))}
                  {(!currentData.chatMessages || currentData.chatMessages.length === 0) && (
                    <div className="h-full flex items-center justify-center opacity-20 italic">Comece a conversa com o time...</div>
                  )}
               </div>
               <div className="p-6 bg-black/40 border-t border-white/5 flex gap-4">
                  <input 
                    value={chatInput}
                    onChange={(e) => setChatInput(e.target.value)}
                    onKeyPress={(e) => e.key === 'Enter' && handleSendChatMessage()}
                    placeholder="Mande sua dúvida ou comemoração..."
                    className="flex-1 bg-black border border-white/10 rounded-2xl px-6 py-4 text-sm text-white outline-none focus:border-[#14b8a6] transition-all"
                  />
                  <button onClick={handleSendChatMessage} className="bg-[#14b8a6] text-black w-14 h-14 rounded-2xl flex items-center justify-center hover:scale-105 transition-transform">
                    <Send className="w-6 h-6" />
                  </button>
               </div>
            </div>
          </div>
        );
      case 'checklists':
        return <ChecklistView tasks={currentData.tasks} onAddTask={(t) => updateCurrentMonthData({ tasks: [{ ...t, id: Date.now().toString(), createdAt: new Date().toISOString() } as Task, ...currentData.tasks] })} onRemoveTask={(id) => updateCurrentMonthData({ tasks: currentData.tasks.filter(t => t.id !== id) })} />;
      case 'my-workspace':
        return <ManagerWorkspace managerId={currentUser.id} clients={currentData.clients} tasks={currentData.tasks} onToggleTask={(id) => updateCurrentMonthData({ tasks: currentData.tasks.map(t => t.id === id ? { ...t, status: t.status === 'COMPLETED' ? 'PENDING' : 'COMPLETED' } : t) })} onUpdateNotes={(id, n) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === id ? { ...c, notes: n } : c) })} onUpdateStatusFlag={(id, f) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === id ? { ...c, statusFlag: f } : c) })} />;
      case 'clients':
        return <SquadsView clients={currentData.clients} onAssignManager={(cid, mid) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === cid ? { ...c, managerId: mid } : c) })} />;
      case 'team':
        return <TeamView team={team} onUpdateRole={(id, r) => setTeam(prev => prev.map(u => u.id === id ? { ...u, role: r } : u))} />;
      case 'notes':
        return (
          <div className="space-y-6 max-w-[1400px] mx-auto">
             <h2 className="text-2xl font-bold text-white uppercase italic tracking-tighter">Wiki & Notas Operacionais</h2>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {currentData.clients.map(c => (
                  <div key={c.id} className="bg-[#111] border border-white/5 p-8 rounded-[32px] space-y-4">
                    <h4 className="font-bold text-white uppercase text-xs tracking-widest">{c.name}</h4>
                    <div className="bg-black/50 p-4 rounded-xl mb-4 border border-teal-500/10">
                       <p className="text-[10px] font-black text-teal-500 uppercase mb-1">Contexto de Venda:</p>
                       <p className="text-xs text-gray-400 italic">"{c.closingNotes || 'Nenhuma observação informada pelo vendedor.'}"</p>
                    </div>
                    <textarea 
                      value={c.notes || ''}
                      onChange={(e) => updateCurrentMonthData({ clients: currentData.clients.map(cl => cl.id === c.id ? { ...cl, notes: e.target.value } : cl) })}
                      placeholder="Anote detalhes da gestão aqui..."
                      className="w-full bg-black border border-white/5 rounded-2xl p-6 text-xs text-gray-400 min-h-[150px] outline-none"
                    />
                  </div>
                ))}
             </div>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="flex h-screen bg-[#0a0a0a] text-gray-300 overflow-hidden font-inter selection:bg-[#14b8a6] selection:text-black">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} currentUser={currentUser} onSwitchUser={(id) => { const u = team.find(x => x.id === id); if(u) setCurrentUser(u); setActiveTab(u.role === UserRole.SALES ? 'commercial' : 'dashboard'); }} />
      <main className="flex-1 flex flex-col h-full overflow-hidden relative">
        <div className="flex-1 overflow-y-auto p-12 custom-scrollbar z-0">
          {renderContent()}
        </div>
        <div className="fixed top-[-100px] right-[-100px] w-[700px] h-[700px] bg-[#14b8a6]/5 blur-[180px] rounded-full pointer-events-none -z-10"></div>
      </main>
    </div>
  );
};

export default App;

