  briefing?: string;
  accessLinks?: string;
  operationalHistory?: string;
}

export interface Client {
  id: string;
  name: string;
  industry: string;
  health: ClientHealth | string;
  progress: number;
  managerId: string;
  salesId?: string;
  closingNotes?: string;
  contractValue: number;
  notes?: string;
  statusFlag: ClientStatus;
