}

export interface ChatMessage {
  id: string;
  senderId: string;
  senderName: string;
  text: string;
  timestamp: string;
}

export interface SalesGoal {
  monthlyTarget: number;
  monthlySuperTarget: number;
  currentValue: number;
  totalSales: number;
  contractFormUrl: string;
  salesNotes?: string;
}

export interface MonthlyData {
  [monthYear: string]: {
    clients: Client[];
    tasks: Task[];
    salesGoal: SalesGoal;
    chatMessages?: ChatMessage[];
  };
}

