import React, { useState } from 'react';
import { Task, User, UserRole } from '../types';
import { MANAGERS } from '../constants';
import { Plus, Send, Users, Trash2, Lock } from 'lucide-react';

interface ChecklistViewProps {
  tasks: Task[];
  currentUser: User;
  onAddTask: (task: Partial<Task>) => void;
  onRemoveTask: (id: string) => void;
}

const ChecklistView: React.FC<ChecklistViewProps> = ({ tasks, currentUser, onAddTask, onRemoveTask }) => {
  const [newTitle, setNewTitle] = useState('');
  const isCEO = currentUser.role === UserRole.CEO;

  // Se não for CEO, ele só pode atribuir para si mesmo
  const [assignee, setAssignee] = useState(isCEO ? 'ALL' : currentUser.id);
  const [type, setType] = useState<'ONCE' | 'WEEKLY'>('ONCE');

  const filteredTasks = isCEO ? tasks : tasks.filter(t => t.assignedTo === currentUser.id || (t.assignedTo === 'ALL' && !isCEO));

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTitle) return;
    onAddTask({
      title: newTitle,
      assignedTo: isCEO ? assignee : currentUser.id,
      type: type,
      status: 'PENDING',
      priority: 'MEDIUM',
      createdAt: new Date().toISOString()
    });
    setNewTitle('');
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 max-w-[1200px] mx-auto">
      <header>
        <h2 className="text-3xl font-black text-white italic uppercase tracking-tighter">Cronogramas Operacionais</h2>
        <p className="text-sm text-gray-400">Organize sua rotina de alta performance.</p>
      </header>

      <form onSubmit={handleSubmit} className="bg-[#111] border border-white/10 p-8 rounded-[32px] flex flex-wrap gap-6 items-end">
        <div className="flex-1 min-w-[300px] space-y-2">
          <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Nova Tarefa / Objetivo</label>
          <input 
            value={newTitle}
            onChange={(e) => setNewTitle(e.target.value)}
            placeholder="O que precisa ser feito hoje?"
            className="w-full bg-[#0a0a0a] border border-white/10 rounded-2xl px-6 py-4 text-sm text-white focus:border-teal-500 outline-none transition-all"
          />
        </div>

        {isCEO ? (
          <div className="space-y-2 min-w-[200px]">
            <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Destinatário (ADM)</label>
            <select 
              value={assignee}
              onChange={(e) => setAssignee(e.target.value)}
              className="w-full bg-[#0a0a0a] border border-white/10 rounded-2xl px-4 py-4 text-sm text-teal-400 font-bold outline-none"
            >
              <option value="ALL">PARA TODA A EQUIPE</option>
              {MANAGERS.map(m => (
                <option key={m.id} value={m.id}>{m.name}</option>
              ))}
            </select>
          </div>
        ) : (
          <div className="space-y-2 min-w-[200px] opacity-50">
             <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest flex items-center gap-1">
               <Lock className="w-2 h-2" /> Atribuir para
             </label>
             <div className="bg-[#0a0a0a] border border-white/5 rounded-2xl px-4 py-4 text-sm text-gray-500 font-bold">
               SOMENTE VOCÊ
             </div>
          </div>
        )}

        <button type="submit" className="bg-[#14b8a6] text-black px-10 py-4 rounded-2xl font-black text-sm hover:scale-105 transition-transform flex items-center gap-2 uppercase italic tracking-tighter">
          <Plus className="w-4 h-4" /> ADICIONAR
        </button>
      </form>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {filteredTasks.map(task => (
          <div key={task.id} className="bg-[#111] border border-white/5 p-6 rounded-[24px] flex items-center justify-between group hover:border-[#14b8a6]/20 transition-all">
            <div className="flex items-center gap-5">
              <div className="p-3 bg-white/5 rounded-xl">
                {task.type === 'WEEKLY' ? <Users className="w-5 h-5 text-blue-400" /> : <Send className="w-5 h-5 text-teal-400" />}
              </div>
              <div>
                <p className="text-sm font-bold text-white uppercase tracking-tighter">{task.title}</p>
                <div className="flex items-center gap-2 text-[9px] text-gray-500 font-black uppercase tracking-widest mt-1">
                  <span>{task.type === 'WEEKLY' ? 'Recorrente' : 'Pontual'}</span>
                  <span>•</span>
                  <span className="text-teal-500/80">ALVO: {task.assignedTo === 'ALL' ? 'EQUIPE' : (task.assignedTo === currentUser.id ? 'VOCÊ' : task.assignedTo)}</span>
                </div>
              </div>
            </div>
            { (isCEO || task.assignedTo === currentUser.id) && (
              <button 
                onClick={() => onRemoveTask(task.id)}
                className="text-gray-700 hover:text-red-500 transition-colors p-2"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            )}
          </div>
        ))}
        {filteredTasks.length === 0 && (
          <div className="col-span-full py-20 text-center opacity-20 italic">
            Nenhuma tarefa ativa no seu cronograma.
          </div>
        )}
      </div>
    </div>
  );
};

export default ChecklistView;

import React, { useState } from 'react';
import { Client, Task, ClientStatus, User } from '../types';
import { CheckCircle2, Circle, StickyNote, Target, Flag, FolderOpen, Info, Link as LinkIcon, History, ChevronDown, ChevronUp } from 'lucide-react';

interface ManagerWorkspaceProps {
  managerId: string;
  clients: Client[];
  tasks: Task[];
  currentUser: User;
  onToggleTask: (taskId: string) => void;
  onUpdateNotes: (clientId: string, notes: string) => void;
  onUpdateStatusFlag: (clientId: string, flag: ClientStatus) => void;
  onUpdateFolder: (clientId: string, folder: Partial<Client['folder']>) => void;
}

const ManagerWorkspace: React.FC<ManagerWorkspaceProps> = ({ 
  managerId, clients, tasks, currentUser, onToggleTask, onUpdateNotes, onUpdateStatusFlag, onUpdateFolder 
}) => {
  const [expandedFolder, setExpandedFolder] = useState<string | null>(null);

  const myClients = clients.filter(c => c.managerId === currentUser.id);
  const myTasks = tasks.filter(t => t.assignedTo === currentUser.id || t.assignedTo === 'ALL');

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-[1400px] mx-auto pb-20">
      <header>
        <h2 className="text-3xl font-black text-white italic tracking-tighter uppercase flex items-center gap-3">
          <FolderOpen className="w-8 h-8 text-[#14b8a6]" /> Minha Carteira Operacional
        </h2>
        <p className="text-gray-400 font-medium">Pasta de Clientes & Documentação Técnica.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">

        {/* Lado Esquerdo: Checklist de Execução */}
        <div className="lg:col-span-4 space-y-6">
          <div className="flex items-center justify-between px-2">
            <h3 className="text-xs font-black text-white uppercase tracking-widest flex items-center gap-2">
              <CheckCircle2 className="w-4 h-4 text-teal-500" /> Fila de Execução
            </h3>
            <span className="text-[10px] bg-white/5 px-2 py-1 rounded text-gray-500 font-black">{myTasks.filter(t => t.status === 'PENDING').length} PENDENTES</span>
          </div>

          <div className="bg-[#111] border border-white/5 rounded-[40px] p-8 space-y-4 max-h-[700px] overflow-y-auto custom-scrollbar">
            {myTasks.length === 0 ? (
              <p className="text-xs text-gray-600 italic text-center py-20">Nenhuma tarefa para sua posição.</p>
            ) : (
              myTasks.map(task => (
                <button 
                  key={task.id}
                  onClick={() => onToggleTask(task.id)}
                  className={`w-full flex items-center gap-4 p-5 rounded-3xl border transition-all text-left ${
                    task.status === 'COMPLETED' ? 'bg-black/40 border-transparent opacity-50' : 'bg-white/[0.03] border-white/5 hover:border-teal-500/20'
                  }`}
                >
                  {task.status === 'COMPLETED' ? <CheckCircle2 className="w-5 h-5 text-teal-500" /> : <Circle className="w-5 h-5 text-gray-700" />}
                  <div>
                    <p className={`text-sm font-bold uppercase tracking-tighter ${task.status === 'COMPLETED' ? 'text-gray-600 line-through' : 'text-white'}`}>{task.title}</p>
                    <span className="text-[9px] text-gray-600 font-black uppercase tracking-widest">{task.type}</span>
                  </div>
                </button>
              ))
            )}
          </div>
        </div>

        {/* Lado Direito: Pastas de Clientes */}
        <div className="lg:col-span-8 space-y-6">
          <h3 className="text-xs font-black text-white uppercase tracking-widest flex items-center gap-2 px-2">
            <Target className="w-4 h-4 text-teal-500" /> Pastas Ativas (Clientes sob sua Gestão)
          </h3>

          <div className="space-y-4">
            {myClients.map(client => (
              <div key={client.id} className="bg-[#111] border border-white/5 rounded-[40px] overflow-hidden transition-all duration-300">

                {/* Cabeçalho da Pasta */}
                <div 
                  className={`p-8 cursor-pointer flex items-center justify-between hover:bg-white/[0.01] transition-colors ${expandedFolder === client.id ? 'bg-white/[0.02]' : ''}`}
                  onClick={() => setExpandedFolder(expandedFolder === client.id ? null : client.id)}
                >
                  <div className="flex items-center gap-6">
                    <div className={`w-3 h-3 rounded-full ${client.statusFlag === 'GREEN' ? 'bg-green-500' : client.statusFlag === 'YELLOW' ? 'bg-yellow-500' : 'bg-red-500'} shadow-lg`}></div>
                    <div>
                      <h4 className="text-2xl font-black text-white uppercase tracking-tighter italic">{client.name}</h4>
                      <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest">{client.industry}</p>
                    </div>
                  </div>

                  <div className="flex items-center gap-4">
                    <div className="text-right hidden sm:block">
                      <p className="text-[10px] font-black text-gray-600 uppercase">Progresso</p>
                      <p className="text-sm font-black text-white">{client.progress}%</p>
                    </div>
                    {expandedFolder === client.id ? <ChevronUp className="text-gray-500" /> : <ChevronDown className="text-gray-500" />}
                  </div>
                </div>

                {/* Conteúdo da Pasta (Expansível) */}
                {expandedFolder === client.id && (
                  <div className="p-8 pt-0 border-t border-white/5 grid grid-cols-1 md:grid-cols-2 gap-8 animate-in slide-in-from-top-4">

                    {/* Briefing & Estratégia */}
                    <div className="space-y-6">
                      <div className="space-y-3">
                        <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest flex items-center gap-2">
                           <Info className="w-3 h-3 text-blue-400" /> Briefing do Projeto
                        </label>
                        <textarea 
                          value={client.folder?.briefing || ''}
                          onChange={(e) => onUpdateFolder(client.id, { briefing: e.target.value })}
                          placeholder="Descreva a estratégia central e os objetivos do cliente..."
                          className="w-full bg-black border border-white/5 rounded-3xl p-6 text-xs text-gray-400 min-h-[120px] outline-none focus:border-blue-500/30 transition-all resize-none"
                        />
                      </div>

                      <div className="space-y-3">
                        <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest flex items-center gap-2">
                           <LinkIcon className="w-3 h-3 text-purple-400" /> Acessos & Links Úteis
                        </label>
                        <textarea 
                          value={client.folder?.accessLinks || ''}
                          onChange={(e) => onUpdateFolder(client.id, { accessLinks: e.target.value })}
                          placeholder="IDs de Contas, Links de Pastas no Drive, Documentos..."
                          className="w-full bg-black border border-white/5 rounded-3xl p-6 text-xs text-gray-400 min-h-[100px] outline-none focus:border-purple-500/30 transition-all resize-none"
                        />
                      </div>
                    </div>

                    {/* Histórico & Notas Operacionais */}
                    <div className="space-y-6">
                      <div className="space-y-3">
                        <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest flex items-center gap-2">
                           <History className="w-3 h-3 text-teal-400" /> Histórico de Alterações / Logs
                        </label>
                        <textarea 
                          value={client.folder?.operationalHistory || ''}
                          onChange={(e) => onUpdateFolder(client.id, { operationalHistory: e.target.value })}
                          placeholder="Log de atividades principais: ex: '25/03: Atualizado layout dos criativos'..."
                          className="w-full bg-black border border-white/5 rounded-3xl p-6 text-xs text-gray-400 min-h-[120px] outline-none focus:border-teal-500/30 transition-all resize-none"
                        />
                      </div>

                      <div className="space-y-3">
                         <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2 flex items-center justify-between">
                           Sinalizador Operacional
                           <span className="text-[8px] opacity-50">CLIQUE PARA MUDAR</span>
                         </label>
                         <div className="flex gap-3">
                            {(['GREEN', 'YELLOW', 'RED'] as ClientStatus[]).map(flag => (
                              <button
                                key={flag}
                                onClick={() => onUpdateStatusFlag(client.id, flag)}
                                className={`flex-1 py-3 rounded-2xl border transition-all ${
                                  client.statusFlag === flag 
                                    ? (flag === 'GREEN' ? 'bg-green-500 border-green-400 text-black' : flag === 'YELLOW' ? 'bg-yellow-500 border-yellow-400 text-black' : 'bg-red-500 border-red-400 text-white')
                                    : 'bg-black border-white/5 text-gray-600 grayscale opacity-30'
                                }`}
                              >
                                <Flag className="w-4 h-4 mx-auto fill-current" />
                              </button>
                            ))}
                         </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            ))}

            {myClients.length === 0 && (
              <div className="bg-[#111] border border-dashed border-white/10 rounded-[40px] p-24 text-center">
                 <p className="text-gray-700 uppercase font-black text-xs tracking-widest">Sem pastas vinculadas à sua ID.</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ManagerWorkspace;

import React, { useState, useEffect } from 'react';
import { UserRole, Client, Task, User, MonthlyData, ClientStatus, SalesGoal, ChatMessage, ClientHealth } from './types';
import { INITIAL_CLIENTS, NAVIGATION_ITEMS, MANAGERS, MONTHS } from './constants';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import SquadsView from './components/SquadsView';
import ChecklistView from './components/ChecklistView';
import ManagerWorkspace from './components/ManagerWorkspace';
import TeamView from './components/TeamView';
import SalesView from './components/SalesView';
import { Send, Hash } from 'lucide-react';

const App: React.FC = () => {
  const currentYear = new Date().getFullYear();
  const currentMonthName = MONTHS[new Date().getMonth()];

  const [currentUser, setCurrentUser] = useState<User>({ id: 'ceo', name: 'Diretor Omega', role: UserRole.CEO });
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedMonth, setSelectedMonth] = useState(`${currentMonthName} ${currentYear}`);
  const [chatInput, setChatInput] = useState('');

  const [db, setDb] = useState<MonthlyData>(() => {
    const saved = localStorage.getItem('omega_db_v7');
    if (saved) return JSON.parse(saved);

    return {
      [`${currentMonthName} ${currentYear}`]: {
        clients: INITIAL_CLIENTS,
        tasks: [],
        salesGoal: {
          monthlyTarget: 100000,
          monthlySuperTarget: 150000,
          currentValue: 0,
          totalSales: 0,
          contractFormUrl: 'https://seulink.com/onboarding',
          salesNotes: ''
        },
        chatMessages: []
      }
    };
  });

  const [team, setTeam] = useState<User[]>(() => {
    const saved = localStorage.getItem('omega_team_v5');
    return saved ? JSON.parse(saved) : [
      { id: 'ceo', name: 'Diretor Omega', role: UserRole.CEO },
      { id: 'm1', name: 'Ricardo Tráfego', role: UserRole.MANAGER },
      { id: 'sm1', name: 'Sofia Social', role: UserRole.SOCIAL_MEDIA },
      { id: 'ed1', name: 'Edu Editor', role: UserRole.EDITOR },
      { id: 'cp1', name: 'Caio Captador', role: UserRole.CAPTADOR },
      { id: 'm3', name: 'Bruno Sales', role: UserRole.SALES, salesCount: 0, salesVolume: 0, personalGoal: 30000, superGoal: 50000 }
    ];
  });

  useEffect(() => {
    localStorage.setItem('omega_db_v7', JSON.stringify(db));
    localStorage.setItem('omega_team_v5', JSON.stringify(team));
  }, [db, team]);

  const currentData = db[selectedMonth] || { clients: [], tasks: [], salesGoal: { monthlyTarget: 100000, currentValue: 0, totalSales: 0, contractFormUrl: '', salesNotes: '' }, chatMessages: [] };

  const updateCurrentMonthData = (updates: Partial<MonthlyData[string]>) => {
    setDb(prev => ({
      ...prev,
      [selectedMonth]: { ...currentData, ...updates }
    }));
  };

  const handleUpdateFolder = (clientId: string, folderUpdates: Partial<Client['folder']>) => {
    updateCurrentMonthData({
      clients: currentData.clients.map(c => c.id === clientId ? {
        ...c,
        folder: { ...(c.folder || {}), ...folderUpdates }
      } : c)
    });
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard clients={currentData.clients} tasks={currentData.tasks} currentUser={currentUser} currentMonth={selectedMonth} months={MONTHS.map(m => `${m} ${currentYear}`)} onMonthChange={setSelectedMonth} />;
      case 'commercial':
        return (
          <SalesView 
            goal={currentData.salesGoal} 
            team={team} 
            clients={currentData.clients}
            currentUser={currentUser} 
            onUpdateGoal={(u) => updateCurrentMonthData({ salesGoal: { ...currentData.salesGoal, ...u } })}
            onRegisterSale={(uid, val, cname) => {
               // Implementação já existente
            }}
            onUpdateUserGoal={(id, pg, sg) => setTeam(prev => prev.map(u => u.id === id ? { ...u, personalGoal: pg, superGoal: sg } : u))}
            onUpdateClientNotes={(cid, n) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === cid ? { ...c, closingNotes: n } : c) })}
          />
        );
      case 'chat':
        return (
          <div className="flex flex-col h-full max-w-[1000px] mx-auto animate-in fade-in duration-500">
             <header className="mb-8">
               <h2 className="text-3xl font-black text-white italic uppercase flex items-center gap-3">
                 <Hash className="w-8 h-8 text-teal-500" /> Comunicação do Time
               </h2>
            </header>
            <div className="flex-1 bg-[#111] border border-white/5 rounded-[40px] flex flex-col overflow-hidden">
               <div className="flex-1 p-8 overflow-y-auto space-y-4 custom-scrollbar">
                  {currentData.chatMessages?.map(msg => (
                    <div key={msg.id} className={`flex flex-col ${msg.senderId === currentUser.id ? 'items-end' : 'items-start'}`}>
                       <span className="text-[9px] font-black text-gray-600 uppercase mb-1">{msg.senderName}</span>
                       <div className={`px-5 py-3 rounded-2xl text-sm ${msg.senderId === currentUser.id ? 'bg-[#14b8a6] text-black font-bold' : 'bg-white/5 text-white'}`}>
                          {msg.text}
                       </div>
                    </div>
                  ))}
               </div>
               <div className="p-6 bg-black/40 flex gap-4 border-t border-white/5">
                  <input value={chatInput} onChange={e => setChatInput(e.target.value)} placeholder="Diga algo..." className="flex-1 bg-black rounded-xl px-4 text-white outline-none" />
                  <button onClick={() => {
                    if(!chatInput) return;
                    const msg: ChatMessage = { id: Date.now().toString(), senderId: currentUser.id, senderName: currentUser.name, text: chatInput, timestamp: '' };
                    updateCurrentMonthData({ chatMessages: [...(currentData.chatMessages || []), msg] });
                    setChatInput('');
                  }} className="bg-teal-500 p-4 rounded-xl text-black font-black">ENVIAR</button>
               </div>
            </div>
          </div>
        );
      case 'checklists':
        return <ChecklistView tasks={currentData.tasks} currentUser={currentUser} onAddTask={(t) => updateCurrentMonthData({ tasks: [{ ...t, id: Date.now().toString(), createdAt: new Date().toISOString() } as Task, ...currentData.tasks] })} onRemoveTask={(id) => updateCurrentMonthData({ tasks: currentData.tasks.filter(t => t.id !== id) })} />;
      case 'my-workspace':
        return <ManagerWorkspace 
          managerId={currentUser.id} 
          clients={currentData.clients} 
          tasks={currentData.tasks} 
          currentUser={currentUser}
          onToggleTask={(id) => updateCurrentMonthData({ tasks: currentData.tasks.map(t => t.id === id ? { ...t, status: t.status === 'COMPLETED' ? 'PENDING' : 'COMPLETED' } : t) })} 
          onUpdateNotes={(id, n) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === id ? { ...c, notes: n } : c) })} 
          onUpdateStatusFlag={(id, f) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === id ? { ...c, statusFlag: f } : c) })} 
          onUpdateFolder={handleUpdateFolder}
        />;
      case 'team':
        return <TeamView team={team} onUpdateRole={(id, r) => setTeam(prev => prev.map(u => u.id === id ? { ...u, role: r } : u))} />;
      case 'clients':
        return <SquadsView clients={currentData.clients} onAssignManager={(cid, mid) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === cid ? { ...c, managerId: mid } : c) })} />;
      default:
        return null;
    }
  };

  return (
    <div className="flex h-screen bg-[#0a0a0a] text-gray-300 overflow-hidden font-inter selection:bg-[#14b8a6] selection:text-black">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} currentUser={currentUser} onSwitchUser={(id) => { const u = team.find(x => x.id === id); if(u) setCurrentUser(u); setActiveTab('dashboard'); }} />
      <main className="flex-1 flex flex-col h-full overflow-hidden relative">
        <div className="flex-1 overflow-y-auto p-12 custom-scrollbar z-0">
          {renderContent()}
        </div>
        <div className="fixed top-[-100px] right-[-100px] w-[700px] h-[700px] bg-[#14b8a6]/5 blur-[180px] rounded-full pointer-events-none -z-10"></div>
      </main>
    </div>
  );
};

export default App;

