export type UserRole = DefaultUserRole | string;

export enum ClientHealth {
  EXCELLENT = 'Excelente',
  STABLE = 'Estável',
  AT_RISK = 'Em Risco',
  CRITICAL = 'Crítico'
}

export type ClientStatus = 'GREEN' | 'YELLOW' | 'RED';

export interface User {
  id: string;
  name: string;
  role: UserRole;
  avatar?: string;
  salesCount?: number;
  salesVolume?: number;
  personalGoal?: number;
  superGoal?: number;
}

export interface ClientFolder {
  briefing?: string;
  accessLinks?: string;
  operationalHistory?: string;
}

export interface Client {
  id: string;
  name: string;
