}

export interface Task {
  id: string;
  title: string;
  assignedTo: string;
  status: 'PENDING' | 'COMPLETED';
  priority: 'LOW' | 'MEDIUM' | 'HIGH';
  type: 'ONCE' | 'WEEKLY';
  createdAt: string;
}

export interface ChatMessage {
  id: string;
  senderId: string;
  senderName: string;
  text: string;
  timestamp: string;
}

export interface SalesGoal {
  monthlyTarget: number;
  monthlySuperTarget: number;
  currentValue: number;
  totalSales: number;
