  salesNotes?: string;
}

export interface MonthlyData {
  [monthYear: string]: {
    clients: Client[];
    tasks: Task[];
    salesGoal: SalesGoal;
    chatMessages?: ChatMessage[];
    availableRoles?: string[]; // Novos cargos salvos por mês ou globalmente
  };
}

