    const vol = seller.salesVolume || 0;
    const g = seller.personalGoal || 10000;
    const sg = seller.superGoal || 15000;
    if (vol >= sg) return 'animate-gold-shine border-amber-400';
    if (vol >= g) return 'border-green-500 bg-green-500/5';
