export const supabase = null;

import React, { useState, useEffect } from 'react';
import { UserRole, DefaultUserRole, Client, Task, User, MonthlyData, ClientStatus, SalesGoal, ChatMessage, ClientHealth } from './types';
import { INITIAL_CLIENTS, NAVIGATION_ITEMS, MANAGERS, MONTHS } from './constants';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import SquadsView from './components/SquadsView';
import ChecklistView from './components/ChecklistView';
import ManagerWorkspace from './components/ManagerWorkspace';
import TeamView from './components/TeamView';
import SalesView from './components/SalesView';
import { Send, Hash, LogIn, ShieldCheck, UserCircle, LogOut } from 'lucide-react';

const App: React.FC = () => {
  const currentYear = new Date().getFullYear();
  const currentMonthName = MONTHS[new Date().getMonth()];
  const monthKey = `${currentMonthName} ${currentYear}`;

  // --- ESTADOS DE SESSÃO E LOGIN ---
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const session = localStorage.getItem('omega_session');
    return session ? JSON.parse(session) : null;
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedMonth, setSelectedMonth] = useState(monthKey);
  const [chatInput, setChatInput] = useState('');

  // --- ESTADOS DE DADOS (BANCO DE DADOS) ---
  const [availableRoles, setAvailableRoles] = useState<string[]>(() => {
    const saved = localStorage.getItem('omega_roles_v2');
    return saved ? JSON.parse(saved) : Object.values(DefaultUserRole);
  });

  const [team, setTeam] = useState<User[]>(() => {
    const saved = localStorage.getItem('omega_team_v7');
    return saved ? JSON.parse(saved) : [
      { id: 'ceo-1', name: 'Diretor Omega', role: DefaultUserRole.CEO, isActive: true },
      { id: 'm1', name: 'Ricardo Tráfego', role: DefaultUserRole.MANAGER, isActive: true },
      { id: 'm3', name: 'Bruno Sales', role: DefaultUserRole.SALES, isActive: true, salesCount: 0, salesVolume: 0, personalGoal: 30000, superGoal: 50000 }
    ];
  });

  const [db, setDb] = useState<MonthlyData>(() => {
    const saved = localStorage.getItem('omega_db_v9');
    if (saved) return JSON.parse(saved);
    return {
      [monthKey]: {
        clients: INITIAL_CLIENTS,
        tasks: [],
        salesGoal: { monthlyTarget: 100000, monthlySuperTarget: 150000, currentValue: 0, totalSales: 0, contractFormUrl: 'https://seulink.com/onboarding' },
        chatMessages: []
      }
    };
  });

  // --- PERSISTÊNCIA ---
  useEffect(() => {
    localStorage.setItem('omega_db_v9', JSON.stringify(db));
    localStorage.setItem('omega_team_v7', JSON.stringify(team));
    localStorage.setItem('omega_roles_v2', JSON.stringify(availableRoles));
    if (currentUser) {
      localStorage.setItem('omega_session', JSON.stringify(currentUser));
      // Segurança: Se o usuário logado for desativado no banco, desloga ele.
      const dbUser = team.find(u => u.id === currentUser.id);
      if (dbUser && !dbUser.isActive) {
        handleLogout();
      }
    }
  }, [db, team, availableRoles, currentUser]);

  const currentData = db[selectedMonth] || { clients: [], tasks: [], salesGoal: { monthlyTarget: 100000, currentValue: 0, totalSales: 0, contractFormUrl: '', salesNotes: '' }, chatMessages: [] };

  const updateCurrentMonthData = (updates: Partial<MonthlyData[string]>) => {
    setDb(prev => ({ ...prev, [selectedMonth]: { ...currentData, ...updates } }));
  };

  // --- LÓGICA DE LOGIN ---
  const [loginForm, setLoginForm] = useState({ name: '', role: '' });

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = team.find(u => u.name.toLowerCase() === loginForm.name.toLowerCase() && u.role === loginForm.role);

    if (user) {
      if (!user.isActive) {
        alert('Seu acesso foi desativado pelo administrador.');
        return;
      }
      setCurrentUser(user);
    } else {
      // Se for o primeiro acesso e não houver ninguém, permite criar o CEO
      if (team.length === 0 || (loginForm.name && loginForm.role === DefaultUserRole.CEO && !team.find(u => u.role === DefaultUserRole.CEO))) {
         const newCeo = { id: 'ceo-main', name: loginForm.name, role: DefaultUserRole.CEO, isActive: true };
         setTeam([newCeo]);
         setCurrentUser(newCeo);
      } else {
        alert('Usuário não encontrado ou cargo incorreto. Contate o suporte.');
      }
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('omega_session');
    setCurrentUser(null);
  };

  // --- GESTÃO DE EQUIPE ---
  const handleAddMember = (name: string, role: UserRole) => {
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      role,
      isActive: true,
      salesCount: 0,
      salesVolume: 0,
      personalGoal: role === DefaultUserRole.SALES ? 20000 : 0,
      superGoal: role === DefaultUserRole.SALES ? 40000 : 0
    };
    setTeam(prev => [...prev, newUser]);
  };

  const handleRemoveMember = (userId: string) => {
    if (confirm('REMOVER DEFINITIVAMENTE? Esta ação apagará o colaborador de todos os registros.')) {
      setTeam(prev => prev.filter(u => u.id !== userId));
    }
  };

  const toggleUserActive = (userId: string) => {
    setTeam(prev => prev.map(u => u.id === userId ? { ...u, isActive: !u.isActive } : u));
  };

  const handleAddRole = (roleName: string) => {
    if (!availableRoles.includes(roleName)) setAvailableRoles([...availableRoles, roleName]);
  };

  // --- RENDERIZAÇÃO DE TELAS ---
  if (!currentUser) {
    return (
      <div className="min-h-screen bg-[#0a0a0a] flex items-center justify-center p-6 font-inter">
        <div className="w-full max-w-md space-y-8 animate-in fade-in zoom-in duration-500">
          <div className="text-center space-y-2">
            <div className="w-20 h-20 bg-[#14b8a6] rounded-[24px] flex items-center justify-center mx-auto mb-6 shadow-[0_20px_50px_rgba(20,184,166,0.3)]">
              <span className="text-4xl font-black text-black">Ω</span>
            </div>
            <h1 className="text-4xl font-black text-white tracking-tighter italic uppercase">Omega Login</h1>
            <p className="text-gray-500 text-sm font-medium">Acesse sua estação de trabalho de alta performance.</p>
          </div>

          <form onSubmit={handleLogin} className="bg-[#111] border border-white/5 p-10 rounded-[40px] shadow-2xl space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest flex items-center gap-2"><UserCircle className="w-3 h-3"/> Nome do Colaborador</label>
              <input 
                required
                value={loginForm.name}
                onChange={e => setLoginForm({ ...loginForm, name: e.target.value })}
                placeholder="Como você está registrado?"
                className="w-full bg-black border border-white/10 rounded-2xl px-6 py-4 text-white outline-none focus:border-[#14b8a6] transition-all"
              />
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest flex items-center gap-2"><ShieldCheck className="w-3 h-3"/> Cargo Operacional</label>
              <select 
                required
                value={loginForm.role}
                onChange={e => setLoginForm({ ...loginForm, role: e.target.value })}
                className="w-full bg-black border border-white/10 rounded-2xl px-6 py-4 text-white outline-none focus:border-[#14b8a6] transition-all appearance-none"
              >
                <option value="">Selecione seu cargo</option>
                {availableRoles.map(r => <option key={r} value={r}>{r.replace('_', ' ')}</option>)}
              </select>
            </div>

            <button type="submit" className="w-full bg-[#14b8a6] text-black py-5 rounded-2xl font-black uppercase italic tracking-tighter flex items-center justify-center gap-3 hover:scale-[1.02] transition-all shadow-[0_15px_30px_rgba(20,184,166,0.2)]">
              ACESSAR DASHBOARD <LogIn className="w-5 h-5" />
            </button>
          </form>

          <p className="text-center text-[10px] text-gray-700 font-black uppercase tracking-[0.2em]">Omega Workplace v2.0 - Secure Session</p>
        </div>
      </div>
    );
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard clients={currentData.clients} tasks={currentData.tasks} currentUser={currentUser} currentMonth={selectedMonth} months={MONTHS.map(m => `${m} ${currentYear}`)} onMonthChange={setSelectedMonth} />;
      case 'team': return (
        <TeamView 
          team={team} 
          currentUser={currentUser} 
          availableRoles={availableRoles} 
          onUpdateRole={(id, r) => setTeam(prev => prev.map(u => u.id === id ? { ...u, role: r } : u))}
          onAddMember={handleAddMember}
          onRemoveMember={handleRemoveMember}
          onAddRole={handleAddRole}
          onToggleActive={toggleUserActive} // Passando nova prop de status
        />
      );
      case 'commercial': return (
        <SalesView 
          goal={currentData.salesGoal} team={team} clients={currentData.clients} currentUser={currentUser}
          onUpdateGoal={u => updateCurrentMonthData({ salesGoal: { ...currentData.salesGoal, ...u } })}
          onRegisterSale={(uid, val, cname) => {
            setTeam(prev => prev.map(usr => usr.id === uid ? { ...usr, salesVolume: (usr.salesVolume || 0) + val } : usr));
            const newClient: Client = { id: Math.random().toString(36).substr(2,9), name: cname, industry: 'Novo Contrato', health: 'Estável', progress: 0, managerId: '', salesId: uid, contractValue: val, statusFlag: 'GREEN', folder: { briefing: '', accessLinks: '', operationalHistory: '' } };
            updateCurrentMonthData({ salesGoal: { ...currentData.salesGoal, currentValue: currentData.salesGoal.currentValue + val, totalSales: currentData.salesGoal.totalSales + 1 }, clients: [...currentData.clients, newClient] });
          }}
          onUpdateUserGoal={(id, pg, sg) => setTeam(prev => prev.map(u => u.id === id ? { ...u, personalGoal: pg, superGoal: sg } : u))}
          onUpdateClientNotes={(cid, n) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === cid ? { ...c, closingNotes: n } : c) })}
        />
      );
      case 'checklists': return <ChecklistView tasks={currentData.tasks} currentUser={currentUser} onAddTask={t => updateCurrentMonthData({ tasks: [{ ...t, id: Date.now().toString() } as Task, ...currentData.tasks] })} onRemoveTask={id => updateCurrentMonthData({ tasks: currentData.tasks.filter(t => t.id !== id) })} />;
      case 'my-workspace': return <ManagerWorkspace managerId={currentUser.id} clients={currentData.clients} tasks={currentData.tasks} currentUser={currentUser} onToggleTask={id => updateCurrentMonthData({ tasks: currentData.tasks.map(t => t.id === id ? { ...t, status: t.status === 'COMPLETED' ? 'PENDING' : 'COMPLETED' } : t) })} onUpdateNotes={(id, n) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === id ? { ...c, notes: n } : c) })} onUpdateStatusFlag={(id, f) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === id ? { ...c, statusFlag: f } : c) })} onUpdateFolder={(id, f) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === id ? { ...c, folder: { ...c.folder, ...f } } : c) })} />;
      case 'chat': return (
        <div className="flex flex-col h-full max-w-[1000px] mx-auto animate-in fade-in duration-500">
           <header className="mb-8 flex justify-between items-center">
             <h2 className="text-3xl font-black text-white italic uppercase flex items-center gap-3"><Hash className="w-8 h-8 text-teal-500" /> Chat do Time</h2>
             <button onClick={handleLogout} className="flex items-center gap-2 text-xs font-black text-red-500 uppercase tracking-widest hover:bg-red-500/10 px-4 py-2 rounded-xl transition-all"><LogOut className="w-4 h-4"/> Sair</button>
           </header>
           <div className="flex-1 bg-[#111] border border-white/5 rounded-[40px] flex flex-col overflow-hidden">
              <div className="flex-1 p-8 overflow-y-auto space-y-4 custom-scrollbar">
                {currentData.chatMessages?.map(msg => (
                  <div key={msg.id} className={`flex flex-col ${msg.senderId === currentUser.id ? 'items-end' : 'items-start'}`}>
                    <span className="text-[9px] font-black text-gray-600 uppercase mb-1">{msg.senderName}</span>
                    <div className={`px-5 py-3 rounded-2xl text-sm ${msg.senderId === currentUser.id ? 'bg-[#14b8a6] text-black font-bold' : 'bg-white/5 text-white'}`}>{msg.text}</div>
                  </div>
                ))}
              </div>
              <div className="p-6 bg-black/40 flex gap-4 border-t border-white/5">
                <input value={chatInput} onChange={e => setChatInput(e.target.value)} onKeyPress={e => e.key === 'Enter' && (()=>{
                  if(!chatInput.trim()) return;
                  const msg = { id: Date.now().toString(), senderId: currentUser.id, senderName: currentUser.name, text: chatInput, timestamp: '' };
                  updateCurrentMonthData({ chatMessages: [...(currentData.chatMessages || []), msg] });
                  setChatInput('');
                })()} placeholder="Diga algo..." className="flex-1 bg-black rounded-xl px-4 text-white outline-none" />
                <button onClick={() => {
                  if(!chatInput.trim()) return;
                  const msg = { id: Date.now().toString(), senderId: currentUser.id, senderName: currentUser.name, text: chatInput, timestamp: '' };
                  updateCurrentMonthData({ chatMessages: [...(currentData.chatMessages || []), msg] });
                  setChatInput('');
                }} className="bg-teal-500 p-4 rounded-xl text-black font-black">ENVIAR</button>
              </div>
           </div>
        </div>
      );
      case 'clients': return <SquadsView clients={currentData.clients} onAssignManager={(cid, mid) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === cid ? { ...c, managerId: mid } : c) })} />;
      default: return null;
    }
  };

  return (
    <div className="flex h-screen bg-[#0a0a0a] text-gray-300 overflow-hidden font-inter selection:bg-[#14b8a6] selection:text-black">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} currentUser={currentUser} onLogout={handleLogout} />
      <main className="flex-1 flex flex-col h-full overflow-hidden relative">
        <div className="flex-1 overflow-y-auto p-12 custom-scrollbar z-0">{renderContent()}</div>
        <div className="fixed top-[-100px] right-[-100px] w-[700px] h-[700px] bg-[#14b8a6]/5 blur-[180px] rounded-full pointer-events-none -z-10"></div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { User, UserRole, DefaultUserRole } from '../types';
import { Mail, ShieldCheck, UserCog, UserPlus, Trash2, ShieldPlus, X, Power, PowerOff } from 'lucide-react';

interface TeamViewProps {
  team: User[];
  currentUser: User;
  availableRoles: string[];
  onUpdateRole: (userId: string, newRole: UserRole) => void;
  onAddMember: (name: string, role: UserRole) => void;
  onRemoveMember: (userId: string) => void;
  onAddRole: (roleName: string) => void;
  onToggleActive: (userId: string) => void;
}

const TeamView: React.FC<TeamViewProps> = ({ 
  team, currentUser, availableRoles, onUpdateRole, onAddMember, onRemoveMember, onAddRole, onToggleActive 
}) => {
  const [isAddingMember, setIsAddingMember] = useState(false);
  const [isAddingRole, setIsAddingRole] = useState(false);
  const [newName, setNewName] = useState('');
  const [newRole, setNewRole] = useState<UserRole>(DefaultUserRole.MANAGER);
  const [newRoleName, setNewRoleName] = useState('');

  const isCEO = currentUser.role === DefaultUserRole.CEO;

  const handleAddMember = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newName.trim()) return;
    onAddMember(newName, newRole);
    setNewName('');
    setIsAddingMember(false);
  };

  const handleAddRole = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newRoleName.trim()) return;
    onAddRole(newRoleName.toUpperCase().replace(/\s+/g, '_'));
    setNewRoleName('');
    setIsAddingRole(false);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 max-w-[1400px] mx-auto pb-24">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h2 className="text-3xl font-black text-white italic uppercase tracking-tighter">Equipe & Performance</h2>
          <p className="text-sm text-gray-400">Gerenciamento de acessos e desligamentos em tempo real.</p>
        </div>

        {isCEO && (
          <div className="flex items-center gap-3">
            <button 
              onClick={() => setIsAddingRole(true)}
              className="bg-white/5 border border-white/10 px-6 py-3 rounded-2xl text-[10px] font-black text-white uppercase hover:bg-white/10 transition-all flex items-center gap-2"
            >
              <ShieldPlus className="w-4 h-4 text-purple-400" /> Criar Novo Cargo
            </button>
            <button 
              onClick={() => setIsAddingMember(true)}
              className="bg-[#14b8a6] px-6 py-3 rounded-2xl text-[10px] font-black text-black uppercase hover:scale-105 transition-all flex items-center gap-2 shadow-[0_10px_20px_rgba(20,184,166,0.2)]"
            >
              <UserPlus className="w-4 h-4" /> Novo Colaborador
            </button>
          </div>
        )}
      </header>

      {/* MODAL ADICIONAR MEMBRO */}
      {isAddingMember && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-md p-4 animate-in fade-in duration-300">
          <form onSubmit={handleAddMember} className="bg-[#111] border border-white/10 p-10 rounded-[48px] w-full max-w-md space-y-6 shadow-2xl relative">
            <button type="button" onClick={() => setIsAddingMember(false)} className="absolute right-8 top-8 text-gray-500 hover:text-white"><X /></button>
            <h3 className="text-2xl font-black text-white uppercase italic">Novo Colaborador</h3>
            <div className="space-y-4">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-500 uppercase">Nome Completo</label>
                <input autoFocus value={newName} onChange={e => setNewName(e.target.value)} className="w-full bg-black border border-white/10 rounded-2xl px-5 py-4 text-white outline-none focus:border-[#14b8a6]" placeholder="Ex: João Silva" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-500 uppercase">Cargo de Acesso</label>
                <select value={newRole} onChange={e => setNewRole(e.target.value)} className="w-full bg-black border border-white/10 rounded-2xl px-5 py-4 text-white outline-none appearance-none">
                  {availableRoles.map(r => <option key={r} value={r}>{r.replace('_', ' ')}</option>)}
                </select>
              </div>
            </div>
            <button type="submit" className="w-full bg-[#14b8a6] text-black py-5 rounded-2xl font-black uppercase text-xs tracking-widest hover:scale-[1.02] transition-all">REGISTRAR ENTRADA</button>
          </form>
        </div>
      )}

      {/* CARDS DA EQUIPE */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {team.map((member) => (
          <div key={member.id} className={`bg-[#111] border rounded-[32px] p-8 transition-all group relative overflow-hidden flex flex-col ${!member.isActive ? 'opacity-50 grayscale border-dashed border-red-500/20' : 'border-white/5 hover:border-[#14b8a6]/20'}`}>
            <div className="absolute right-[-10px] top-[-10px] opacity-[0.02] pointer-events-none group-hover:opacity-[0.05] transition-opacity">
              <UserCog className="w-24 h-24" />
            </div>

            <div className="flex items-start justify-between mb-6">
              <div className="flex items-center gap-4">
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center border shadow-inner ${member.isActive ? 'bg-teal-500/10 border-teal-500/20' : 'bg-red-500/10 border-red-500/20'}`}>
                  <span className={`text-xl font-black uppercase ${member.isActive ? 'text-teal-400' : 'text-red-400'}`}>{member.name[0]}</span>
                </div>
                <div>
                  <h4 className="text-white font-bold text-lg uppercase tracking-tighter italic">{member.name}</h4>
                  <div className="flex items-center gap-1.5 mt-1">
                    <span className={`text-[9px] font-black uppercase tracking-widest ${member.isActive ? 'text-teal-500' : 'text-red-500'}`}>
                      {member.isActive ? '• ACESSO ATIVO' : '• ACESSO BLOQUEADO'}
                    </span>
                  </div>
                </div>
              </div>

              {isCEO && member.id !== currentUser.id && (
                <div className="flex gap-2">
                   <button 
                    onClick={() => onToggleActive(member.id)}
                    className={`p-2 rounded-xl transition-all ${member.isActive ? 'text-gray-600 hover:text-red-500 hover:bg-red-500/10' : 'text-red-500 hover:text-green-500 hover:bg-green-500/10'}`}
                    title={member.isActive ? "Desativar Acesso" : "Reativar Acesso"}
                  >
                    {member.isActive ? <PowerOff className="w-4 h-4" /> : <Power className="w-4 h-4" />}
                  </button>
                  <button 
                    onClick={() => onRemoveMember(member.id)}
                    className="p-2 text-gray-700 hover:text-red-600 hover:bg-red-600/10 rounded-xl transition-all"
                    title="Excluir Definitivamente"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              )}
            </div>

            <div className="space-y-4 relative z-10 flex-1 flex flex-col justify-end">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest flex items-center gap-2"><ShieldCheck className="w-3 h-3" /> Nível de Acesso</label>
                {isCEO ? (
                  <select 
                    value={member.role}
                    onChange={(e) => onUpdateRole(member.id, e.target.value)}
                    className="w-full bg-black/40 border border-white/5 rounded-xl px-4 py-3 text-xs font-bold text-teal-400 outline-none focus:border-teal-500 transition-all cursor-pointer"
                  >
                    {availableRoles.map(role => (
                      <option key={role} value={role}>{role.replace('_', ' ')}</option>
                    ))}
                  </select>
                ) : (
                  <div className="w-full bg-black/40 border border-white/5 rounded-xl px-4 py-3 text-xs font-bold text-gray-500 uppercase tracking-widest">
                    {member.role.replace('_', ' ')}
                  </div>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

