import React, { useState, useEffect } from 'react';
import { UserRole, DefaultUserRole, Client, Task, User, MonthlyData, ClientStatus, SalesGoal, ChatMessage, ClientHealth } from './types';
import { INITIAL_CLIENTS, NAVIGATION_ITEMS, MANAGERS, MONTHS } from './constants';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import SquadsView from './components/SquadsView';
import ChecklistView from './components/ChecklistView';
import ManagerWorkspace from './components/ManagerWorkspace';
import TeamView from './components/TeamView';
import SalesView from './components/SalesView';
import { Send, Hash, LogIn, ShieldCheck, UserCircle, LogOut } from 'lucide-react';

const App: React.FC = () => {
  const currentYear = new Date().getFullYear();
  const currentMonthName = MONTHS[new Date().getMonth()];
  const monthKey = `${currentMonthName} ${currentYear}`;

  // --- ESTADOS DE SESSÃO E LOGIN ---
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const session = localStorage.getItem('omega_session');
    return session ? JSON.parse(session) : null;
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedMonth, setSelectedMonth] = useState(monthKey);
  const [chatInput, setChatInput] = useState('');

  // --- ESTADOS DE DADOS (BANCO DE DADOS) ---
  const [availableRoles, setAvailableRoles] = useState<string[]>(() => {
    const saved = localStorage.getItem('omega_roles_v2');
    return saved ? JSON.parse(saved) : Object.values(DefaultUserRole);
  });

  const [team, setTeam] = useState<User[]>(() => {
    const saved = localStorage.getItem('omega_team_v7');
    return saved ? JSON.parse(saved) : [
      { id: 'ceo-1', name: 'Diretor Omega', role: DefaultUserRole.CEO, isActive: true },
      { id: 'm1', name: 'Ricardo Tráfego', role: DefaultUserRole.MANAGER, isActive: true },
      { id: 'm3', name: 'Bruno Sales', role: DefaultUserRole.SALES, isActive: true, salesCount: 0, salesVolume: 0, personalGoal: 30000, superGoal: 50000 }
    ];
  });

  const [db, setDb] = useState<MonthlyData>(() => {
    const saved = localStorage.getItem('omega_db_v9');
    if (saved) return JSON.parse(saved);
    return {
      [monthKey]: {
        clients: INITIAL_CLIENTS,
        tasks: [],
        salesGoal: { monthlyTarget: 100000, monthlySuperTarget: 150000, currentValue: 0, totalSales: 0, contractFormUrl: 'https://seulink.com/onboarding' },
        chatMessages: []
      }
    };
  });

  // --- PERSISTÊNCIA ---
  useEffect(() => {
    localStorage.setItem('omega_db_v9', JSON.stringify(db));
    localStorage.setItem('omega_team_v7', JSON.stringify(team));
    localStorage.setItem('omega_roles_v2', JSON.stringify(availableRoles));
    if (currentUser) {
      localStorage.setItem('omega_session', JSON.stringify(currentUser));
      // Segurança: Se o usuário logado for desativado no banco, desloga ele.
      const dbUser = team.find(u => u.id === currentUser.id);
      if (dbUser && !dbUser.isActive) {
        handleLogout();
      }
    }
  }, [db, team, availableRoles, currentUser]);

  // Fix: Ensure currentData fallback includes all required SalesGoal properties to prevent type errors in setters and children
  const currentData = db[selectedMonth] || { 
    clients: [], 
    tasks: [], 
    salesGoal: { 
      monthlyTarget: 100000, 
      monthlySuperTarget: 150000, 
      currentValue: 0, 
      totalSales: 0, 
      contractFormUrl: 'https://seulink.com/onboarding', 
      salesNotes: '' 
    }, 
    chatMessages: [] 
  };

  const updateCurrentMonthData = (updates: Partial<MonthlyData[string]>) => {
    setDb(prev => ({ ...prev, [selectedMonth]: { ...currentData, ...updates } }));
  };

  // --- LÓGICA DE LOGIN ---
  const [loginForm, setLoginForm] = useState({ name: '', role: '' });

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = team.find(u => u.name.toLowerCase() === loginForm.name.toLowerCase() && u.role === loginForm.role);

    if (user) {
      if (!user.isActive) {
        alert('Seu acesso foi desativado pelo administrador.');
        return;
      }
      setCurrentUser(user);
    } else {
      // Se for o primeiro acesso e não houver ninguém, permite criar o CEO
      if (team.length === 0 || (loginForm.name && loginForm.role === DefaultUserRole.CEO && !team.find(u => u.role === DefaultUserRole.CEO))) {
         const newCeo = { id: 'ceo-main', name: loginForm.name, role: DefaultUserRole.CEO, isActive: true };
         setTeam([newCeo]);
         setCurrentUser(newCeo);
      } else {
        alert('Usuário não encontrado ou cargo incorreto. Contate o suporte.');
      }
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('omega_session');
    setCurrentUser(null);
  };

  // --- GESTÃO DE EQUIPE ---
  const handleAddMember = (name: string, role: UserRole) => {
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      role,
      isActive: true,
      salesCount: 0,
      salesVolume: 0,
      personalGoal: role === DefaultUserRole.SALES ? 20000 : 0,
      superGoal: role === DefaultUserRole.SALES ? 40000 : 0
    };
    setTeam(prev => [...prev, newUser]);
  };

  const handleRemoveMember = (userId: string) => {
    if (confirm('REMOVER DEFINITIVAMENTE? Esta ação apagará o colaborador de todos os registros.')) {
      setTeam(prev => prev.filter(u => u.id !== userId));
    }
  };

  const toggleUserActive = (userId: string) => {
    setTeam(prev => prev.map(u => u.id === userId ? { ...u, isActive: !u.isActive } : u));
  };

  const handleAddRole = (roleName: string) => {
    if (!availableRoles.includes(roleName)) setAvailableRoles([...availableRoles, roleName]);
  };

  // --- RENDERIZAÇÃO DE TELAS ---
  if (!currentUser) {
    return (
      <div className="min-h-screen bg-[#0a0a0a] flex items-center justify-center p-6 font-inter">
        <div className="w-full max-w-md space-y-8 animate-in fade-in zoom-in duration-500">
          <div className="text-center space-y-2">
            <div className="w-20 h-20 bg-[#14b8a6] rounded-[24px] flex items-center justify-center mx-auto mb-6 shadow-[0_20px_50px_rgba(20,184,166,0.3)]">
              <span className="text-4xl font-black text-black">Ω</span>
            </div>
            <h1 className="text-4xl font-black text-white tracking-tighter italic uppercase">Omega Login</h1>
            <p className="text-gray-500 text-sm font-medium">Acesse sua estação de trabalho de alta performance.</p>
          </div>

          <form onSubmit={handleLogin} className="bg-[#111] border border-white/5 p-10 rounded-[40px] shadow-2xl space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest flex items-center gap-2"><UserCircle className="w-3 h-3"/> Nome do Colaborador</label>
              <input 
                required
                value={loginForm.name}
                onChange={e => setLoginForm({ ...loginForm, name: e.target.value })}
                placeholder="Como você está registrado?"
                className="w-full bg-black border border-white/10 rounded-2xl px-6 py-4 text-white outline-none focus:border-[#14b8a6] transition-all"
              />
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest flex items-center gap-2"><ShieldCheck className="w-3 h-3"/> Cargo Operacional</label>
              <select 
                required
                value={loginForm.role}
                onChange={e => setLoginForm({ ...loginForm, role: e.target.value })}
                className="w-full bg-black border border-white/10 rounded-2xl px-6 py-4 text-white outline-none focus:border-[#14b8a6] transition-all appearance-none"
              >
                <option value="">Selecione seu cargo</option>
                {availableRoles.map(r => <option key={r} value={r}>{r.replace('_', ' ')}</option>)}
              </select>
            </div>

            <button type="submit" className="w-full bg-[#14b8a6] text-black py-5 rounded-2xl font-black uppercase italic tracking-tighter flex items-center justify-center gap-3 hover:scale-[1.02] transition-all shadow-[0_15px_30px_rgba(20,184,166,0.2)]">
              ACESSAR DASHBOARD <LogIn className="w-5 h-5" />
            </button>
          </form>

          <p className="text-center text-[10px] text-gray-700 font-black uppercase tracking-[0.2em]">Omega Workplace v2.0 - Secure Session</p>
        </div>
      </div>
    );
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard clients={currentData.clients} tasks={currentData.tasks} currentUser={currentUser} currentMonth={selectedMonth} months={MONTHS.map(m => `${m} ${currentYear}`)} onMonthChange={setSelectedMonth} />;
      case 'team': return (
        <TeamView 
          team={team} 
          currentUser={currentUser} 
          availableRoles={availableRoles} 
          onUpdateRole={(id, r) => setTeam(prev => prev.map(u => u.id === id ? { ...u, role: r } : u))}
          onAddMember={handleAddMember}
          onRemoveMember={handleRemoveMember}
          onAddRole={handleAddRole}
          onToggleActive={toggleUserActive} // Passando nova prop de status
        />
      );
      case 'commercial': return (
        <SalesView 
          goal={currentData.salesGoal} team={team} clients={currentData.clients} currentUser={currentUser}
          onUpdateGoal={u => updateCurrentMonthData({ salesGoal: { ...currentData.salesGoal, ...u } })}
          onRegisterSale={(uid, val, cname) => {
            setTeam(prev => prev.map(usr => usr.id === uid ? { ...usr, salesVolume: (usr.salesVolume || 0) + val } : usr));
            const newClient: Client = { id: Math.random().toString(36).substr(2,9), name: cname, industry: 'Novo Contrato', health: 'Estável', progress: 0, managerId: '', salesId: uid, contractValue: val, statusFlag: 'GREEN', folder: { briefing: '', accessLinks: '', operationalHistory: '' } };
            updateCurrentMonthData({ salesGoal: { ...currentData.salesGoal, currentValue: currentData.salesGoal.currentValue + val, totalSales: currentData.salesGoal.totalSales + 1 }, clients: [...currentData.clients, newClient] });
          }}
          onUpdateUserGoal={(id, pg, sg) => setTeam(prev => prev.map(u => u.id === id ? { ...u, personalGoal: pg, superGoal: sg } : u))}
          onUpdateClientNotes={(cid, n) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === cid ? { ...c, closingNotes: n } : c) })}
        />
      );
