      case 'my-workspace': return <ManagerWorkspace managerId={currentUser.id} clients={currentData.clients} tasks={currentData.tasks} currentUser={currentUser} onToggleTask={id => updateCurrentMonthData({ tasks: currentData.tasks.map(t => t.id === id ? { ...t, status: t.status === 'COMPLETED' ? 'PENDING' : 'COMPLETED' } : t) })} onUpdateNotes={(id, n) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === id ? { ...c, notes: n } : c) })} onUpdateStatusFlag={(id, f) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === id ? { ...c, statusFlag: f } : c) })} onUpdateFolder={(id, f) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === id ? { ...c, folder: { ...c.folder, ...f } } : c) })} />;
      case 'chat': return (
        <div className="flex flex-col h-full max-w-[1000px] mx-auto animate-in fade-in duration-500">
           <header className="mb-8 flex justify-between items-center">
             <h2 className="text-3xl font-black text-white italic uppercase flex items-center gap-3"><Hash className="w-8 h-8 text-teal-500" /> Chat do Time</h2>
             <button onClick={handleLogout} className="flex items-center gap-2 text-xs font-black text-red-500 uppercase tracking-widest hover:bg-red-500/10 px-4 py-2 rounded-xl transition-all"><LogOut className="w-4 h-4"/> Sair</button>
