           <div className="flex-1 bg-[#111] border border-white/5 rounded-[40px] flex flex-col overflow-hidden">
              <div className="flex-1 p-8 overflow-y-auto space-y-4 custom-scrollbar">
                {currentData.chatMessages?.map(msg => (
                  <div key={msg.id} className={`flex flex-col ${msg.senderId === currentUser.id ? 'items-end' : 'items-start'}`}>
                    <span className="text-[9px] font-black text-gray-600 uppercase mb-1">{msg.senderName}</span>
                    <div className={`px-5 py-3 rounded-2xl text-sm ${msg.senderId === currentUser.id ? 'bg-[#14b8a6] text-black font-bold' : 'bg-white/5 text-white'}`}>{msg.text}</div>
                  </div>
                ))}
              </div>
              <div className="p-6 bg-black/40 flex gap-4 border-t border-white/5">
                <input value={chatInput} onChange={e => setChatInput(e.target.value)} onKeyPress={e => e.key === 'Enter' && (()=>{
                  if(!chatInput.trim()) return;
                  const msg = { id: Date.now().toString(), senderId: currentUser.id, senderName: currentUser.name, text: chatInput, timestamp: '' };
                  updateCurrentMonthData({ chatMessages: [...(currentData.chatMessages || []), msg] });
                  setChatInput('');
                })()} placeholder="Diga algo..." className="flex-1 bg-black rounded-xl px-4 text-white outline-none" />
                <button onClick={() => {
                  if(!chatInput.trim()) return;
                  const msg = { id: Date.now().toString(), senderId: currentUser.id, senderName: currentUser.name, text: chatInput, timestamp: '' };
                  updateCurrentMonthData({ chatMessages: [...(currentData.chatMessages || []), msg] });
                  setChatInput('');
                }} className="bg-teal-500 p-4 rounded-xl text-black font-black">ENVIAR</button>
              </div>
           </div>
        </div>
      );
      case 'clients': return <SquadsView clients={currentData.clients} onAssignManager={(cid, mid) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === cid ? { ...c, managerId: mid } : c) })} />;
      default: return null;
