             </h3>
             <div className="flex items-center gap-2 text-[10px] text-gray-600 font-bold uppercase tracking-widest">
                <button onClick={() => setCurrentDrivePath(null)} className="hover:text-purple-400">Raiz</button>
                {breadcrumbs.map(bc => (
                  <React.Fragment key={bc.id}>
                    <ChevronRight className="w-3 h-3" />
                    <button onClick={() => setCurrentDrivePath(bc.id)} className="hover:text-purple-400 max-w-[100px] truncate">{bc.name}</button>
                  </React.Fragment>
                ))}
             </div>
          </div>
          <div className="flex gap-2">
            <button onClick={handleCreateFolder} className="p-2 bg-white/5 hover:bg-white/10 rounded-xl text-gray-400 hover:text-white transition-all"><FolderPlus className="w-5 h-5"/></button>
            <button onClick={handleCreateFile} className="p-2 bg-white/5 hover:bg-white/10 rounded-xl text-gray-400 hover:text-white transition-all"><FilePlus className="w-5 h-5"/></button>
          </div>
        </div>

        <div className="bg-[#111] border border-white/5 rounded-[48px] p-8 min-h-[300px] relative overflow-hidden group">
           <div className="grid grid-cols-2 md:grid-cols-4 xl:grid-cols-6 gap-6 relative z-10">
              {currentDrivePath && (
                <button 
                  onClick={() => {
                    const current = drive.find(i => i.id === currentDrivePath);
                    setCurrentDrivePath(current?.parentId || null);
                  }}
                  className="flex flex-col items-center justify-center p-6 rounded-3xl bg-white/[0.02] border border-dashed border-white/5 text-gray-600 hover:text-white hover:bg-white/5 transition-all"
                >
                  <ArrowLeft className="w-8 h-8 mb-2" />
                  <span className="text-[10px] font-black uppercase">Voltar</span>
                </button>
              )}

              {currentItems.map(item => (
                <div 
                  key={item.id} 
                  onClick={() => item.type === 'FOLDER' ? setCurrentDrivePath(item.id) : setEditingFile(item)}
                  className="flex flex-col items-center justify-center p-6 rounded-[32px] bg-black/40 border border-white/5 hover:border-purple-500/30 hover:bg-white/[0.03] cursor-pointer transition-all group/item relative"
                >
                  <button 
                    onClick={(e) => handleDeleteItem(e, item.id)}
                    className="absolute top-4 right-4 p-2 text-gray-700 hover:text-red-500 opacity-0 group-hover/item:opacity-100 transition-opacity"
                  >
                    <Trash2 className="w-3 h-3" />
                  </button>

                  {item.type === 'FOLDER' ? (
                    <div className="w-16 h-12 bg-purple-500/20 rounded-lg relative mb-4 shadow-[0_10px_30px_rgba(168,85,247,0.2)]">
                      <div className="absolute top-[-4px] left-0 w-8 h-2 bg-purple-500 rounded-t-sm"></div>
                    </div>
                  ) : (
                    <FileText className="w-12 h-12 text-blue-400/50 mb-4" />
                  )}
                  <span className="text-xs font-bold text-gray-400 text-center truncate w-full px-2">{item.name}</span>
                </div>
              ))}

              {currentItems.length === 0 && !currentDrivePath && (
                <div className="col-span-full py-20 text-center opacity-20 italic">
                  Seu drive está vazio. Comece a organizar seus recursos.
                </div>
              )}
           </div>
        </div>
      </section>

      {/* EDITOR DE ARQUIVO (MODAL) */}
      {editingFile && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/95 backdrop-blur-xl p-6">
           <div className="w-full max-w-4xl bg-[#111] border border-white/10 rounded-[48px] overflow-hidden flex flex-col shadow-2xl h-[80vh]">
              <div className="p-8 bg-black/40 border-b border-white/5 flex items-center justify-between">
                 <div className="flex items-center gap-4">
                   <FileText className="w-6 h-6 text-purple-400" />
                   <h3 className="text-xl font-black text-white italic uppercase">{editingFile.name}</h3>
                 </div>
                 <div className="flex gap-4">
                   <button onClick={() => setEditingFile(null)} className="px-6 py-2 text-gray-500 font-bold uppercase text-xs">Cancelar</button>
                   <button onClick={handleSaveFile} className="px-8 py-2 bg-purple-500 text-black font-black uppercase text-xs rounded-xl shadow-lg shadow-purple-500/20">Salvar Alterações</button>
                 </div>
              </div>
              <textarea 
                autoFocus
                value={editingFile.content || ''}
                onChange={(e) => setEditingFile({...editingFile, content: e.target.value})}
                placeholder="Comece a digitar suas anotações, roteiros ou links..."
                className="flex-1 w-full bg-transparent p-12 text-gray-300 text-lg outline-none resize-none font-medium leading-relaxed"
              />
           </div>
        </div>
      )}

      {/* --- RESTO DA WORKSPACE --- */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-4 space-y-6">
          <div className="flex items-center justify-between px-2">
            <h3 className="text-xs font-black text-white uppercase tracking-widest flex items-center gap-2">
              <CheckCircle2 className="w-4 h-4 text-teal-500" /> Fila de Execução
            </h3>
            <span className="text-[10px] bg-white/5 px-2 py-1 rounded text-gray-500 font-black">{myTasks.filter(t => t.status === 'PENDING').length} PENDENTES</span>
          </div>
          <div className="bg-[#111] border border-white/5 rounded-[48px] p-8 space-y-4 max-h-[700px] overflow-y-auto custom-scrollbar">
            {myTasks.map(task => (
                <button key={task.id} onClick={() => onToggleTask(task.id)} className={`w-full flex items-center gap-4 p-6 rounded-[32px] border transition-all text-left ${task.status === 'COMPLETED' ? 'bg-black/40 border-transparent opacity-40' : 'bg-white/[0.03] border-white/5 hover:border-teal-500/20'}`}>
                  {task.status === 'COMPLETED' ? <CheckCircle2 className="w-5 h-5 text-teal-500" /> : <Circle className="w-5 h-5 text-gray-700" />}
                  <div>
                    <p className={`text-sm font-bold uppercase tracking-tighter ${task.status === 'COMPLETED' ? 'text-gray-600 line-through' : 'text-white'}`}>{task.title}</p>
                    <span className="text-[9px] text-gray-600 font-black uppercase tracking-widest">{task.type}</span>
                  </div>
                </button>
            ))}
          </div>
        </div>

        <div className="lg:col-span-8 space-y-6">
          <h3 className="text-xs font-black text-white uppercase tracking-widest flex items-center gap-2 px-2">
            <Target className="w-4 h-4 text-teal-500" /> Pastas Ativas de Clientes
          </h3>
          <div className="space-y-4">
            {myClients.map(client => (
              <div key={client.id} className="bg-[#111] border border-white/5 rounded-[48px] overflow-hidden transition-all duration-300">
                <div className={`p-10 cursor-pointer flex items-center justify-between hover:bg-white/[0.01] ${expandedFolder === client.id ? 'bg-white/[0.02]' : ''}`} onClick={() => setExpandedFolder(expandedFolder === client.id ? null : client.id)}>
                  <div className="flex items-center gap-6">
                    <div className={`w-3 h-3 rounded-full ${client.statusFlag === 'GREEN' ? 'bg-green-500' : client.statusFlag === 'YELLOW' ? 'bg-yellow-500' : 'bg-red-500'} shadow-lg`}></div>
                    <div><h4 className="text-2xl font-black text-white uppercase tracking-tighter italic">{client.name}</h4><p className="text-[10px] text-gray-500 font-black uppercase tracking-widest">{client.industry}</p></div>
                  </div>
                  <div className="flex items-center gap-4">{expandedFolder === client.id ? <ChevronUp className="text-gray-500" /> : <ChevronDown className="text-gray-500" />}</div>
                </div>
                {expandedFolder === client.id && (
                  <div className="p-10 pt-0 border-t border-white/5 grid grid-cols-1 md:grid-cols-2 gap-10 animate-in slide-in-from-top-4">
                    <div className="space-y-6">
                      <div className="space-y-3"><label className="text-[10px] font-black text-gray-500 uppercase flex items-center gap-2"><Info className="w-3 h-3 text-blue-400" /> Briefing do Projeto</label>
                        <textarea value={client.folder?.briefing || ''} onChange={(e) => onUpdateFolder(client.id, { briefing: e.target.value })} placeholder="Estratégia central..." className="w-full bg-black border border-white/5 rounded-3xl p-6 text-xs text-gray-400 min-h-[120px] outline-none focus:border-blue-500/30 transition-all resize-none" />
