export const dbService = {
  saveState: async (state: AppState) => {
    // Backup Local sempre ativo
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));

    if (!supabase || supabase.supabaseUrl.includes('seu-projeto')) {
      console.warn('Supabase não configurado. Dados salvos apenas localmente.');
      return;
    }

    try {
      const { error } = await supabase
        .from('omega_store')
        .upsert({ id: 1, state: state });

      if (error) {
        console.error('Erro de permissão ou tabela no Supabase:', error.message);
      }
    } catch (e) {
      console.error('Erro de conexão física com o Supabase (Verifique sua URL):', e);
    }
  },

  loadState: async (): Promise<AppState | null> => {
    // Tenta Supabase primeiro
    if (supabase && !supabase.supabaseUrl.includes('seu-projeto')) {
      try {
        const { data, error } = await supabase
          .from('omega_store')
          .select('state')
          .eq('id', 1)
          .single();

        if (data && data.state && Object.keys(data.state).length > 0) {
          console.log('✅ Sincronizado com Nuvem Ômega');
          return data.state as AppState;
        }

        if (error) console.log('Aviso Supabase:', error.message);
      } catch (e) {
        console.warn('Offline ou Erro de DNS. Usando LocalStorage.');
      }
    }

    const localData = localStorage.getItem(STORAGE_KEY);
    if (localData) {
      console.log('📂 Carregado do cache local');
      return JSON.parse(localData);
    }

    return null;
  },
};

