import { AppState } from '../types';
import { supabase } from '../supabaseClient';

const STORAGE_KEY = 'omega_v2_data';

export const dbService = {
  saveState: async (state: AppState): Promise<boolean> => {
    // 1. Sempre salva no LocalStorage como segurança absoluta (Backup local)
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));

    if (!supabase) return false;

    try {
      const { error } = await supabase
        .from('omega_store')
        .upsert({ id: 1, state: state });

      if (error) {
        console.warn('⚠️ Erro de gravação na Nuvem (Verifique as tabelas):', error.message);
        return false;
      }
      return true;
    } catch (e) {
      // Aqui captura o "Failed to fetch" sem quebrar o app
      console.warn('📡 Falha de conexão com a Nuvem. Operando em modo cache local.');
      return false;
    }
  },

  loadState: async (): Promise<AppState | null> => {
    if (supabase) {
      try {
        const { data, error } = await supabase
          .from('omega_store')
          .select('state')
          .eq('id', 1)
          .single();

        if (data && data.state && Object.keys(data.state).length > 0) {
          console.log('✅ Sincronizado com Nuvem Ômega');
          return data.state as AppState;
        }
      } catch (e) {
        console.warn('📡 Erro de rede ao carregar. Usando backup local.');
      }
    }

    const localData = localStorage.getItem(STORAGE_KEY);
    if (localData) {
      console.log('📂 Backup local carregado');
      return JSON.parse(localData);
    }

    return null;
  },
};

