          // Garante que o CEO sempre tenha acesso mesmo que o banco de dados mude
          const hasCEO = saved.team.some(u => u.email === 'assessoriaomega1@gmail.com');
          if (!hasCEO) {
            saved.team.push({ 
              id: 'ceo-master', 
              name: 'Diretoria Ômega', 
              email: 'assessoriaomega1@gmail.com', 
              password: 'admin', 
              role: DefaultUserRole.CEO, 
              isActive: true 
