          setTeam(saved.team);
          setAvailableRoles(saved.availableRoles);
          setDb(saved.db);
          setIsSynced(true);
        }
      } catch (err) {
        console.error("Erro na inicialização:", err);
      } finally {
        setIsLoading(false);
      }
    };
    initApp();
