const STORAGE_KEY = 'omega_v2_data';

export const dbService = {
  saveState: async (state: AppState): Promise<boolean> => {
    // 1. Sempre salva no LocalStorage como segurança absoluta (Backup local)
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));

    if (!supabase) return false;

    try {
      const { error } = await supabase
        .from('omega_store')
        .upsert({ id: 1, state: state });

      if (error) {
        // Log silenciado para evitar poluição visual em caso de erro de rede comum
        return false;
      }
      return true;
    } catch (e) {
      // Captura o "Failed to fetch" (CORS, Adblock, etc)
      return false;
    }
  },

  loadState: async (): Promise<AppState | null> => {
    // Tenta carregar do LocalStorage primeiro para velocidade
    const localData = localStorage.getItem(STORAGE_KEY);
    let localParsed: AppState | null = null;
    if (localData) {
      localParsed = JSON.parse(localData);
    }

    if (supabase) {
      try {
        const { data, error } = await supabase
          .from('omega_store')
          .select('state')
          .eq('id', 1)
          .single();

        if (data && data.state && Object.keys(data.state).length > 0) {
          console.log('✅ Nuvem Ômega Sincronizada');
          return data.state as AppState;
        }
      } catch (e) {
        // Ignora erro de rede e usa o local
      }
    }

    if (localParsed) {
      console.log('📂 Cache local carregado');
      return localParsed;
    }

    return null;
  },
};

import { AppState } from '../types';
import { supabase } from '../supabaseClient';

const STORAGE_KEY = 'omega_v2_data';

export const dbService = {
  saveState: async (state: AppState): Promise<boolean> => {
    // 1. Sempre salva no LocalStorage (Segurança local)
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));

    if (!supabase) {
      console.warn("⚠️ Supabase não configurado.");
      return false;
    }

    try {
      // Tenta gravar na nuvem
      const { error } = await supabase
        .from('omega_store')
        .upsert({ id: 1, state: state }, { onConflict: 'id' });

      if (error) {
        console.error('❌ Erro Supabase:', error.message);
        console.info('Dica: Verifique se a tabela "omega_store" com colunas "id" (int8) e "state" (jsonb) existe.');
        return false;
      }

      return true;
    } catch (e: any) {
      // Captura especificamente o erro de rede
      if (e.message === 'Failed to fetch' || e.name === 'TypeError') {
        console.warn('📡 Bloqueio de Rede: O navegador ou um AdBlocker está impedindo a conexão com o Supabase.');
      } else {
        console.error('❌ Erro inesperado na gravação:', e);
      }
      return false;
    }
  },

  loadState: async (): Promise<AppState | null> => {
    // Tenta carregar do local primeiro para ser instantâneo
    const localData = localStorage.getItem(STORAGE_KEY);
    let localParsed: AppState | null = null;
    if (localData) {
      try {
        localParsed = JSON.parse(localData);
      } catch (e) {
        console.error("Erro ao ler cache local");
      }
    }

    if (supabase) {
      try {
        const { data, error } = await supabase
          .from('omega_store')
          .select('state')
          .eq('id', 1)
          .maybeSingle();

        if (error) throw error;

        if (data && data.state) {
          console.log('✅ Sincronizado com Nuvem Ômega');
          return data.state as AppState;
        }
      } catch (e) {
        console.warn('📡 Falha ao buscar dados na nuvem. Usando local.');
      }
    }

    return localParsed;
  },
};

