import { AppState } from '../types';
import { supabase } from '../supabaseClient';

const STORAGE_KEY = 'omega_v2_data';
const SUPABASE_URL = 'https://chzkslqbpmlpepvydacu.supabase.co';

export const dbService = {
  // Testa se o domínio do Supabase está acessível (útil para detectar AdBlockers)
  testConnection: async (): Promise<{ success: boolean; error?: string }> => {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 5000);

      const response = await fetch(`${SUPABASE_URL}/rest/v1/`, {
        method: 'GET',
        headers: { 'apikey': 'ping' }, // Apenas para testar alcance
        signal: controller.signal
      });

      clearTimeout(timeoutId);
      return { success: true };
    } catch (e: any) {
      console.error("📡 Erro de Conectividade:", e.message);
      if (e.message.includes('Failed to fetch') || e.name === 'TypeError') {
        return { 
          success: false, 
          error: "O navegador bloqueou a conexão. Desative AdBlockers ou VPNs para este site." 
        };
      }
      return { success: false, error: e.message };
    }
  },

  saveState: async (state: AppState): Promise<{ success: boolean; error?: string }> => {
    // 1. Backup Local imediato
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));

    if (!supabase) return { success: false, error: "Supabase não configurado." };

    try {
      const { error } = await supabase
        .from('omega_store')
        .upsert({ id: 1, state: state }, { onConflict: 'id' });

      if (error) {
        console.error('❌ Erro Supabase:', error.message);
        return { success: false, error: error.message };
      }

      return { success: true };
    } catch (e: any) {
      const isNetworkError = e.message?.includes('Failed to fetch') || e.name === 'TypeError';
      const errorMsg = isNetworkError 
        ? "Erro de Rede (Possível AdBlock/Bloqueio)" 
        : (e.message || "Erro desconhecido");

      return { success: false, error: errorMsg };
    }
  },

  loadState: async (): Promise<AppState | null> => {
    const localData = localStorage.getItem(STORAGE_KEY);
    let localParsed: AppState | null = null;

    if (localData) {
      try {
        localParsed = JSON.parse(localData);
      } catch (e) {
        console.error("Erro ao ler cache local");
      }
    }

    if (supabase) {
      try {
        const { data, error } = await supabase
          .from('omega_store')
          .select('state')
          .eq('id', 1)
          .maybeSingle();

        if (error) throw error;

        if (data && data.state) {
          console.log('✅ Dados carregados da Nuvem');
          return data.state as AppState;
        }
      } catch (e) {
        console.warn('📡 Falha ao buscar dados na nuvem. Usando backup local.');
      }
    }

    return localParsed;
  },
};

import React, { useState, useEffect, useCallback } from 'react';
import { UserRole, DefaultUserRole, Client, Task, User, MonthlyData, ClientStatus, SalesGoal, ChatMessage, ClientHealth, DriveItem } from './types';
import { INITIAL_CLIENTS, NAVIGATION_ITEMS, MANAGERS, MONTHS } from './constants';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import SquadsView from './components/SquadsView';
import ChecklistView from './components/ChecklistView';
import ManagerWorkspace from './components/ManagerWorkspace';
import TeamView from './components/TeamView';
import SalesView from './components/SalesView';
import WikiView from './components/WikiView';
import Auth from './components/Auth';
import { dbService } from './services/database';
import { Hash, Loader2, AlertCircle } from 'lucide-react';

const App: React.FC = () => {
  const currentYear = new Date().getFullYear();
  const currentMonthName = MONTHS[new Date().getMonth()];
  const monthKey = `${currentMonthName} ${currentYear}`;

  const [isLoading, setIsLoading] = useState(true);
  const [isSynced, setIsSynced] = useState(false);
  const [syncError, setSyncError] = useState<string | null>(null);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedMonth, setSelectedMonth] = useState(monthKey);
  const [chatInput, setChatInput] = useState('');

  const [availableRoles, setAvailableRoles] = useState<string[]>(Object.values(DefaultUserRole));

  const CEO_DEFAULT: User = { 
    id: 'ceo-master', 
    name: 'Diretoria Ômega', 
    email: 'assessoriaomega1@gmail.com', 
    password: 'admin', 
    role: DefaultUserRole.CEO, 
    isActive: true 
  };

  const [team, setTeam] = useState<User[]>([CEO_DEFAULT]);

  const [db, setDb] = useState<MonthlyData>({
    [monthKey]: {
      clients: INITIAL_CLIENTS,
      tasks: [],
      salesGoal: { monthlyTarget: 100000, monthlySuperTarget: 150000, currentValue: 0, totalSales: 0, contractFormUrl: 'https://seulink.com/onboarding' },
      chatMessages: [],
      drive: [],
      wiki: []
    }
  });

  const syncToCloud = useCallback(async () => {
    if (isLoading) return;
    const result = await dbService.saveState({ team, availableRoles, db });
    setIsSynced(result.success);
    setSyncError(result.error || null);
    if (!result.success) {
      console.warn("⚠️ Sincronização falhou:", result.error);
    }
  }, [team, availableRoles, db, isLoading]);

  // Carregamento Inicial
  useEffect(() => {
    const initApp = async () => {
      setIsLoading(true);
      try {
        const saved = await dbService.loadState();
        if (saved) {
          const otherMembers = (saved.team || []).filter(u => u.email.toLowerCase() !== CEO_DEFAULT.email.toLowerCase());
          setTeam([CEO_DEFAULT, ...otherMembers]);
          setAvailableRoles(saved.availableRoles || Object.values(DefaultUserRole));
          setDb(saved.db);
          setIsSynced(true);
          setSyncError(null);
        } else {
          setTeam([CEO_DEFAULT]);
        }
      } catch (err) {
        console.error("Erro crítico na inicialização:", err);
        setTeam([CEO_DEFAULT]);
      } finally {
        setIsLoading(false);
      }
    };
    initApp();
  }, []);

  // Sincronização automática com debouncing
  useEffect(() => {
    if (!isLoading) {
      const saveTimeout = setTimeout(syncToCloud, 1000);
      return () => clearTimeout(saveTimeout);
    }
  }, [team, availableRoles, db, isLoading, syncToCloud]);

  const currentData = db[selectedMonth] || { 
    clients: [], 
    tasks: [], 
    salesGoal: { monthlyTarget: 100000, monthlySuperTarget: 150000, currentValue: 0, totalSales: 0, contractFormUrl: 'https://seulink.com/onboarding', salesNotes: '' }, 
    chatMessages: [],
    drive: [],
    wiki: []
  };

  const updateCurrentMonthData = (updates: Partial<MonthlyData[string]>) => {
    setDb(prev => ({ ...prev, [selectedMonth]: { ...currentData, ...updates } }));
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setActiveTab('dashboard');
  };

  const handleUpdateTeamMember = (updatedUser: User) => {
    setTeam(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#0a0a0a] flex flex-col items-center justify-center gap-6">
        <div className="w-16 h-16 bg-[#14b8a6] rounded-2xl flex items-center justify-center animate-pulse shadow-[0_0_50px_rgba(20,184,166,0.3)]">
          <span className="text-black font-black text-3xl">Ω</span>
        </div>
        <div className="flex flex-col items-center gap-2">
          <div className="flex items-center gap-3 text-teal-500 font-black uppercase tracking-[0.3em] text-[10px]">
            <Loader2 className="w-4 h-4 animate-spin" /> Sincronizando Sistemas Ômega
          </div>
          <p className="text-gray-600 text-[9px] font-bold uppercase tracking-widest">Aguardando resposta do servidor...</p>
        </div>
      </div>
    );
  }

  const renderContent = () => {
    if (!currentUser) return null;

    switch (activeTab) {
      case 'dashboard': return <Dashboard clients={currentData.clients.filter(c => !c.isPaused)} tasks={currentData.tasks} currentUser={currentUser} currentMonth={selectedMonth} months={MONTHS.map(m => `${m} ${currentYear}`)} onMonthChange={setSelectedMonth} />;
      case 'team': return (
        <TeamView 
          team={team} currentUser={currentUser} availableRoles={availableRoles} 
          onUpdateRole={(id, r) => setTeam(prev => prev.map(u => u.id === id ? { ...u, role: r } : u))}
          onAddMember={(name, role, email) => {
            const exists = team.some(u => u.email.toLowerCase() === email.toLowerCase());
            if(exists) { alert("Este email já está cadastrado."); return; }
            setTeam(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), name, email: email.toLowerCase(), role, isActive: true }]);
          }}
          onRemoveMember={(id) => {
            if (id === 'ceo-master') { alert("Acesso de diretoria não pode ser removido."); return; }
            setTeam(prev => prev.filter(u => u.id !== id));
          }}
          onAddRole={(role) => setAvailableRoles([...availableRoles, role])}
          onToggleActive={(id) => setTeam(prev => prev.map(u => u.id === id ? { ...u, isActive: !u.isActive } : u))} 
        />
      );
      case 'commercial': return (
        <SalesView 
          goal={currentData.salesGoal} team={team} clients={currentData.clients} currentUser={currentUser}
          onUpdateGoal={u => updateCurrentMonthData({ salesGoal: { ...currentData.salesGoal, ...u } })}
          onRegisterSale={(uid, val, cname) => {
            setTeam(prev => prev.map(usr => usr.id === uid ? { ...usr, salesVolume: (usr.salesVolume || 0) + val } : usr));
            const newClient: Client = { id: Math.random().toString(36).substr(2,9), name: cname, industry: 'Novo Contrato', health: 'Estável', progress: 0, managerId: '', salesId: uid, contractValue: val, statusFlag: 'GREEN', isPaused: false, folder: { briefing: '', accessLinks: '', operationalHistory: '' } };
            updateCurrentMonthData({ salesGoal: { ...currentData.salesGoal, currentValue: currentData.salesGoal.currentValue + val, totalSales: currentData.salesGoal.totalSales + 1 }, clients: [...currentData.clients, newClient] });
          }}
          onUpdateUserGoal={(id, pg, sg) => setTeam(prev => prev.map(u => u.id === id ? { ...u, personalGoal: pg, superGoal: sg } : u))}
          onUpdateClientNotes={(cid, n) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === cid ? { ...c, closingNotes: n } : c) })}
        />
      );
      case 'checklists': return <ChecklistView tasks={currentData.tasks} currentUser={currentUser} onAddTask={t => updateCurrentMonthData({ tasks: [{ ...t, id: Date.now().toString() } as Task, ...currentData.tasks] })} onRemoveTask={id => updateCurrentMonthData({ tasks: currentData.tasks.filter(t => t.id !== id) })} />;
      case 'my-workspace': return (
        <ManagerWorkspace 
          managerId={currentUser.id} 
          clients={currentData.clients} 
          tasks={currentData.tasks} 
          currentUser={currentUser} 
          drive={currentData.drive || []}
          onUpdateDrive={items => updateCurrentMonthData({ drive: items })}
          onToggleTask={id => updateCurrentMonthData({ tasks: currentData.tasks.map(t => t.id === id ? { ...t, status: t.status === 'COMPLETED' ? 'PENDING' : 'COMPLETED' } : t) })} 
          onUpdateNotes={(id, n) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === cid ? { ...c, notes: n } : c) })} 
          onUpdateStatusFlag={(id, f) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === id ? { ...c, statusFlag: f } : c) })} 
          onUpdateFolder={(id, f) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === id ? { ...c, folder: { ...c.folder, ...f } } : c) })} 
        />
      );
      case 'clients': return (
        <SquadsView 
          clients={currentData.clients} 
          currentUser={currentUser}
          onAssignManager={(cid, mid) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === cid ? { ...c, managerId: mid } : c) })} 
          onRemoveClient={(cid) => updateCurrentMonthData({ clients: currentData.clients.filter(c => c.id !== cid) })}
          onTogglePauseClient={(cid) => updateCurrentMonthData({ clients: currentData.clients.map(c => c.id === cid ? { ...c, isPaused: !c.isPaused } : c) })}
        />
      );
      case 'notes': return <WikiView wiki={currentData.wiki || []} currentUser={currentUser} onUpdateWiki={items => updateCurrentMonthData({ wiki: items })} />;
      case 'chat': return (
        <div className="flex flex-col h-full max-w-[1000px] mx-auto">
           <header className="mb-8 flex justify-between items-center px-4"><h2 className="text-3xl font-black text-white italic uppercase flex items-center gap-3"><Hash className="w-8 h-8 text-teal-500" /> Comunicação Interna</h2></header>
           <div className="flex-1 bg-[#111] border border-white/5 rounded-[40px] flex flex-col overflow-hidden shadow-2xl">
