interface SidebarProps {
  activeTab: string;
  setActiveTab: (tab: string) => void;
  currentUser: User;
  onLogout: () => void;
  isSynced?: boolean;
  syncError?: string | null;
}

const Sidebar: React.FC<SidebarProps> = ({ 
  activeTab, 
  setActiveTab, 
  currentUser, 
  onLogout, 
  isSynced = false,
  syncError = null
}) => {
  const [isRetrying, setIsRetrying] = useState(false);
  const filteredNav = NAVIGATION_ITEMS.filter(item => 
    (item.roles as string[]).includes(currentUser.role)
  );

  const handleRetry = async () => {
    setIsRetrying(true);
    // Testa a conexão básica antes de tudo
    const check = await dbService.testConnection();
    if (!check.success) {
      alert(`⚠️ Problema Detectado: ${check.error}\n\nSe você estiver usando AdBlock ou VPN, desative-os para permitir a sincronização com o banco de dados.`);
    } else {
      // Força um recarregamento para tentar nova conexão limpa
      window.location.reload();
    }
    setIsRetrying(false);
