import { AppState } from '../types';
import { supabase } from '../supabaseClient';

const STORAGE_KEY = 'omega_v2_data';
const SUPABASE_URL = 'https://chzkslqbpmlpepvydacu.supabase.co';

export const dbService = {
  diagnoseConnection: async (): Promise<{ status: 'CONNECTED' | 'BLOCKED' | 'SERVER_ERROR' | 'OFFLINE', message?: string }> => {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 8000); // Aumentado para 8s

      const response = await fetch(`${SUPABASE_URL}/rest/v1/`, {
        method: 'GET',
        headers: { 'apikey': 'ping' },
        cache: 'no-store', // Força buscar da rede, não do cache
        signal: controller.signal
      });

      clearTimeout(timeoutId);
      return { status: 'CONNECTED' };
    } catch (e: any) {
      if (e.name === 'AbortError') return { status: 'OFFLINE', message: 'Conexão lenta ou offline.' };
      if (e.message.includes('fetch') || e.name === 'TypeError') {
        return { 
          status: 'BLOCKED', 
          message: 'Domínio Supabase bloqueado pelo Navegador (AdBlock/VPN).' 
        };
      }
      return { status: 'SERVER_ERROR', message: e.message };
    }
  },

  saveState: async (state: AppState): Promise<{ success: boolean; error?: string; isNetworkBlock?: boolean }> => {
    // Backup Local Garantido
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));

    if (!supabase) return { success: false, error: "Configuração ausente." };

    try {
      // Tenta salvar na nuvem
      const { error } = await supabase
        .from('omega_store')
        .upsert({ id: 1, state: state }, { onConflict: 'id' });

      if (error) throw error;
      return { success: true };
    } catch (e: any) {
      const isBlock = e.message?.includes('fetch') || e.name === 'TypeError' || e.status === 0;
      console.error("📡 Status de Sincronização:", isBlock ? "Bloqueado por Extensão" : e.message);

      return { 
        success: false, 
        error: isBlock ? "Navegador bloqueou o envio." : e.message,
        isNetworkBlock: isBlock
      };
    }
  },

  loadState: async (): Promise<AppState | null> => {
    const localData = localStorage.getItem(STORAGE_KEY);
    let localParsed: AppState | null = null;

    if (localData) {
      try { localParsed = JSON.parse(localData); } catch (e) { console.error("Erro JSON local"); }
    }

    // Tenta puxar a versão mais recente da nuvem
    if (supabase) {
      try {
        const { data, error } = await supabase
          .from('omega_store')
          .select('state')
          .eq('id', 1)
          .maybeSingle();

        if (!error && data?.state) {
          console.log("✅ Dados sincronizados da Nuvem");
          return data.state as AppState;
        }
      } catch (e) {
        console.warn("⚠️ Usando dados locais (Nuvem inacessível)");
      }
    }

    return localParsed;
  },
};

