        {error && (
          <div className="mb-6 p-4 bg-red-500/10 border border-red-500/20 rounded-2xl flex items-center gap-3 text-red-400 text-[11px] font-bold animate-shake">
            <AlertIcon className="w-4 h-4 shrink-0" />
